INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('f02aabc8-bf3f-5a65-aea0-0cce2813649c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 7, 7, 'A wind-turbine tower sways back and forth at 0.80 Hz. Calculate the angular frequency of the sway.', NULL, 1, 'numeric'::answer_type, '5.027', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 0.80 = 5.03 rad s⁻¹. Mark scheme (1 mark). A1: ω = 5.03 rad s⁻¹.', 1),
('0131bb79-177b-5775-b49b-4a963ce1420d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 8, 8, 'Mains electricity in Europe alternates at 50 Hz. Calculate its angular frequency.', NULL, 1, 'numeric'::answer_type, '314.2', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 50 = 314 rad s⁻¹. Mark scheme (1 mark). A1: ω = 314 rad s⁻¹.', 1),
('189783a4-5b0d-5708-8629-ea54174364b9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 9, 9, 'An oscillator has angular frequency 31.4 rad s⁻¹. Calculate its frequency and period. Give the period.', NULL, 1, 'numeric'::answer_type, '0.2001', 's', false, NULL, false, NULL, 'f = ω/2π = 31.4 ÷ 2π = 5.00 Hz. T = 1/f = 2π ÷ 31.4 = 0.200 s. Mark scheme (2 marks). C1: f = ω/2π or T = 2π/ω. A1: T = 0.200 s.', 2),
('76836b57-b2c4-582d-9fb5-913dbd50a7ec', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 10, 10, 'Which expression gives the angular frequency ω of an oscillation of period T?', NULL, 1, 'multiple_choice'::answer_type, '2π/T', NULL, false, NULL, false, NULL, 'ω = 2πf and f = 1/T, so ω = 2π/T. Mark scheme (1 mark). B1: C (2π/T).', 1),
('eee18db5-974c-58fc-a879-a06af5b17b7e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 11, 11, 'What is the unit of angular frequency?', NULL, 1, 'multiple_choice'::answer_type, 'rad s⁻¹', NULL, false, NULL, false, NULL, 'Angular frequency is the rate of change of phase angle: radians per second. Mark scheme (1 mark). B1: A (rad s⁻¹).', 1),
('02ffff20-3e61-52df-b227-a9a51630b2c1', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 12, 12, 'A heartbeat has a period of 0.75 s. Calculate its angular frequency.', NULL, 1, 'numeric'::answer_type, '8.378', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 0.75 = 8.38 rad s⁻¹. Mark scheme (2 marks). C1: ω = 2π/T. A1: ω = 8.38 rad s⁻¹.', 2),
('356b67d4-fc65-5452-b133-32fbb7038e6d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 13, 13, 'Calculate the frequency of an oscillation with angular frequency 2.0 × 10³ rad s⁻¹.', NULL, 1, 'numeric'::answer_type, '318.3', 'Hz', false, NULL, false, NULL, 'f = ω/2π = 2.0 × 10³ ÷ 2π = 318 Hz. Mark scheme (2 marks). C1: f = ω/2π. A1: f = 318 Hz.', 2),
('d3dfded1-1eb1-5bfb-bc0e-965f53783524', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 14, 14, 'Two oscillators have frequencies f and 3f. What is the ratio of their angular frequencies (second/first)?', NULL, 1, 'multiple_choice'::answer_type, '3', NULL, false, NULL, false, NULL, 'ω = 2πf ∝ f, so the ratio is 3. Mark scheme (1 mark). B1: D (3).', 1),
('7fec642e-9883-5f9f-8952-577f83eed604', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 15, 15, 'A mass on a spring has ω = 15 rad s⁻¹. How many oscillations does it make in 10 s?', NULL, 1, 'numeric'::answer_type, '23.87', NULL, false, 0.02, false, NULL, 'f = ω/2π = 15 ÷ 2π = 2.39 Hz, so N = ft = 2.387 × 10 = 23.9. Mark scheme (2 marks). C1: f = ω/2π, N = ft. A1: N = 23.9.', 2),
('190a18b3-424d-597d-b488-f80ed242e476', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 16, 16, 'A quartz crystal in a watch vibrates at 32 768 Hz. Calculate its angular frequency.', NULL, 1, 'numeric'::answer_type, '2.059e5', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 32768 = 2.06 × 10⁵ rad s⁻¹. Mark scheme (2 marks). C1: ω = 2πf. A1: ω = 2.06 × 10⁵ rad s⁻¹.', 2),
('e9724a5c-a541-5a8b-9a4d-7f1d4ac31ca3', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 17, 17, 'An oscillation has angular frequency 4π rad s⁻¹. What is its period?', NULL, 1, 'multiple_choice'::answer_type, '0.50 s', NULL, false, NULL, false, NULL, 'T = 2π/ω = 2π/4π = 0.50 s. Mark scheme (1 mark). B1: B (0.50 s).', 1),
('192f37eb-9f2b-5efa-82d3-587f591205eb', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 18, 18, 'A pendulum of length 0.50 m swings with small oscillations. Calculate its angular frequency. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '4.429', 'rad s⁻¹', false, NULL, false, NULL, 'ω = √(g/L) = √(9.81 ÷ 0.50) = 4.43 rad s⁻¹. Mark scheme (2 marks). C1: ω = √(g/L). A1: ω = 4.43 rad s⁻¹.', 2),
('6159f1ce-001c-57e5-bd99-aa6eb3ecf4a7', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 19, 19, 'A 0.80 kg mass on a spring of constant 320 N m⁻¹ oscillates. Calculate ω.', NULL, 1, 'numeric'::answer_type, '20', 'rad s⁻¹', false, NULL, false, NULL, 'ω = √(k/m) = √(320 ÷ 0.80) = 20 rad s⁻¹. Mark scheme (2 marks). C1: ω = √(k/m). A1: ω = 20 rad s⁻¹.', 2),
('9138d34c-efd7-5f28-a487-c636661ebf81', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 20, 20, 'Why is angular frequency used in s.h.m. equations instead of frequency?', NULL, 1, 'multiple_choice'::answer_type, 'It makes the equations neater: x = x₀ sin ωt instead of x = x₀ sin 2πft', NULL, false, NULL, false, NULL, 'ω = 2πf absorbs the 2π, so the phase angle ωt is in radians directly. Mark scheme (1 mark). B1: C (It makes the equations neater: x = x₀ sin ωt instead of x = x₀ sin 2πft).', 1),
('48e4b5b7-be27-5a00-93c8-ae4b0d07333d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 21, 21, 'A vibrating molecule bond has ω = 1.6 × 10¹⁴ rad s⁻¹. Calculate its frequency.', NULL, 1, 'numeric'::answer_type, '2.546e13', 'Hz', false, NULL, false, NULL, 'f = ω/2π = 1.6 × 10¹⁴ ÷ 2π = 2.55 × 10¹³ Hz. Mark scheme (2 marks). C1: f = ω/2π. A1: f = 2.55 × 10¹³ Hz.', 2),
('84e58539-28ee-5b63-af47-155012187819', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 22, 22, 'A child on a swing makes 12 complete swings in 30 s. Calculate the angular frequency and the length of the swing (treat it as a simple pendulum). Give the length. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '1.553', 'm', false, NULL, false, NULL, 'f = 12 ÷ 30 = 0.40 Hz, ω = 2πf = 2.51 rad s⁻¹. ω² = g/L, so L = g/ω² = 9.81 ÷ (2.51)² = 1.55 m. Mark scheme (3 marks). C1: f = N/t. C1: ω = 2πf. C1: L = g/ω².', 3),
('ebec2db4-b9d0-593a-9ccf-deea2f98cbd9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 23, 23, 'A spring of constant 45 N m⁻¹ has a mass hung on it, giving ω = 7.5 rad s⁻¹. Calculate the mass.', NULL, 2, 'numeric'::answer_type, '0.8', 'kg', false, NULL, false, NULL, 'ω² = k/m, so m = k/ω² = 45 ÷ 7.5² = 0.800 kg. Mark scheme (3 marks). C1: ω² = k/m. C1: rearranged. A1: m = 0.800 kg.', 3),
('61ca3081-3e02-51d8-b9c4-c0adfc9058ae', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 24, 24, 'The mass on a spring is increased by a factor of 4. What happens to the angular frequency?', NULL, 2, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'ω = √(k/m) ∝ 1/√m: √4 = 2, so ω halves. Mark scheme (3 marks). C1: ω ∝ 1/√m. C1: factor of 2. A1: A (It halves).', 3),
('9832d382-4f6c-5ba2-b321-3476c4dd2ad7', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 25, 25, 'A mass of 0.30 kg on a spring oscillates with frequency 2.2 Hz. A second mass is added and the frequency falls to 1.6 Hz. Calculate the added mass.', NULL, 2, 'numeric'::answer_type, '0.2672', 'kg', false, NULL, false, NULL, 'f ∝ 1/√m, so m₂ = m₁(f₁/f₂)² = 0.30 × (2.2 ÷ 1.6)² = 0.567 kg. Added mass = 0.5672 − 0.30 = 0.267 kg. Mark scheme (4 marks). C1: f ∝ 1/√m. C1: m₂. C1: subtract. A1: Δm = 0.267 kg.', 4),
('1eaf49b8-2679-5a40-8813-1e02c421a68c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 26, 26, 'An oscillation has angular frequency 12 rad s⁻¹. Calculate the time taken for the phase to increase by π/3 rad.', NULL, 2, 'numeric'::answer_type, '0.08727', 's', false, NULL, false, NULL, 't = Δφ/ω = (π/3) ÷ 12 = 0.0873 s. Mark scheme (3 marks). C1: phase = ωt. C1: t = Δφ/ω. A1: t = 0.0873 s.', 3),
('05227492-98d8-5a22-a80b-aeff3bfb05e5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 27, 27, 'Two pendulums have angular frequencies 2.0 rad s⁻¹ and 2.5 rad s⁻¹ in the same place. What is the ratio of their lengths (first/second)?', NULL, 2, 'multiple_choice'::answer_type, '1.56', NULL, false, NULL, false, NULL, 'ω² = g/L, so L ∝ 1/ω²: L₁/L₂ = (2.5/2.0)² = 1.5625. Mark scheme (3 marks). C1: L ∝ 1/ω². C1: ratio. A1: D (1.56).', 3),
('71ab9d81-1ab6-5ea9-8230-d67727f48a11', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 28, 28, 'A guitar string vibrates at angular frequency 1380 rad s⁻¹. Calculate the number of vibrations in 0.050 s.', NULL, 2, 'numeric'::answer_type, '10.98', NULL, false, 0.02, false, NULL, 'f = 1380 ÷ 2π = 220 Hz. N = ft = 219.6 × 0.050 = 11.0. Mark scheme (3 marks). C1: f = ω/2π. C1: N = ft. A1: N = 11.0.', 3),
('11bc921e-8378-5227-b8b6-3a774af68b32', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 29, 29, 'A pendulum on Mars has length 0.60 m and angular frequency 2.48 rad s⁻¹. Calculate g on Mars, and the period of a 1.0 m pendulum there. Give the period.', NULL, 2, 'numeric'::answer_type, '3.271', 's', false, NULL, false, NULL, 'g = ω²L = 2.48² × 0.60 = 3.69 N kg⁻¹. For L = 1.0 m: T = 2π√(L/g) = 2π × √(1.0 ÷ 3.690) = 3.27 s. Mark scheme (4 marks). C1: g = ω²L. C1: T = 2π√(L/g). C1: substitution. A1: T = 3.27 s.', 4),
('987e561c-6d9e-5cb1-a192-a1f990f2b144', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 30, 30, 'A student writes ω = 2π/f. Why is this wrong?', NULL, 2, 'multiple_choice'::answer_type, 'ω = 2πf; 2π/f has the wrong unit (rad s, not rad s⁻¹)', NULL, false, NULL, false, NULL, 'Angular frequency is 2π radians per period: ω = 2π/T = 2πf. Mark scheme (3 marks). C1: ω = 2πf. C1: unit check. A1: B (ω = 2πf; 2π/f has the wrong unit (rad s, not rad s⁻¹)).', 3),
('e3fafff6-26ca-5338-b7e1-b0e32805d49f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 31, 31, 'An oscillator has period 0.25 s. Calculate its angular frequency and the angle (in degrees) its phase advances in 0.10 s. Give the angle.', NULL, 2, 'numeric'::answer_type, '144', '°', false, NULL, false, NULL, 'ω = 2π ÷ 0.25 = 25.1 rad s⁻¹. Phase = ωt = 25.1 × 0.10 = 2.51 rad. In degrees: 2.513 × 180 ÷ π = 144°. Mark scheme (3 marks). C1: ω = 2π/T. C1: φ = ωt. C1: to degrees.', 3),
('bb5b416c-0bfb-5918-a847-a9d6eaab6acb', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 32, 32, 'A diatomic molecule is modelled as two equal atoms on a spring; the effective (reduced) mass is 1.15 × 10⁻²⁶ kg and the bond constant is 1900 N m⁻¹. Calculate the angular frequency and frequency of the vibration. Give the frequency.', NULL, 2, 'numeric'::answer_type, '6.469e13', 'Hz', false, NULL, false, NULL, 'ω = √(k/μ) = √(1900 ÷ 1.15 × 10⁻²⁶) = 4.06 × 10¹⁴ rad s⁻¹. f = ω/2π = 4.065 × 10¹⁴ ÷ 2π = 6.47 × 10¹³ Hz. Mark scheme (4 marks). C1: ω = √(k/m). C1: substitution. C1: f = ω/2π. A1: f = 6.47 × 10¹³ Hz.', 4),
('5fb66fc0-d847-56d2-b011-caad6ddc4ea9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 33, 33, 'A spring–mass system has ω = 10 rad s⁻¹ on Earth. On the Moon, what is ω?', NULL, 2, 'multiple_choice'::answer_type, '10 rad s⁻¹', NULL, false, NULL, false, NULL, 'ω = √(k/m) does not depend on g, so it is unchanged. Mark scheme (3 marks). C1: ω = √(k/m). C1: no g. A1: C (10 rad s⁻¹).', 3),
('6f3e9402-564b-5a3d-9f42-7fe4a9931967', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 34, 34, 'A pendulum has angular frequency 3.13 rad s⁻¹. Calculate its length. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '1.001', 'm', false, NULL, false, NULL, 'L = g/ω² = 9.81 ÷ 3.13² = 1.00 m. Mark scheme (3 marks). C1: ω² = g/L. C1: rearranged. A1: L = 1.00 m.', 3),
('fbfb51f1-c616-56f1-b460-bae9e404f267', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 35, 35, 'A car on its suspension bounces at 1.2 Hz when empty (mass 1000 kg). Calculate ω and the suspension spring constant. Give the spring constant.', NULL, 2, 'numeric'::answer_type, '56849', 'N m⁻¹', false, NULL, false, NULL, 'ω = 2π × 1.2 = 7.54 rad s⁻¹. k = mω² = 1000 × (7.54)² = 5.68 × 10⁴ N m⁻¹. Mark scheme (3 marks). C1: ω = 2πf. C1: k = mω². A1: k = 5.68 × 10⁴ N m⁻¹.', 3),
('5b0f04da-8eea-5cac-bc2d-637f2002c292', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 36, 36, 'Spring A (constant k) and spring B (constant 4k) each carry the same mass. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'B oscillates with twice the angular frequency of A', NULL, false, NULL, false, NULL, 'ω = √(k/m) ∝ √k: √4 = 2. Mark scheme (4 marks). C1: ω ∝ √k. C1: factor 2. C1: B faster. A1: A (B oscillates with twice the angular frequency of A).', 4),
('67e4f29f-a8d7-57e6-a4f8-b4c8f958b29d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 37, 37, 'A tuning fork has frequency 440 Hz. Calculate how long it takes for its phase to change by 3π rad.', NULL, 2, 'numeric'::answer_type, '0.003409', 's', false, NULL, false, NULL, 't = Δφ/ω = 3π ÷ (2π × 440) = 0.00341 s. Mark scheme (3 marks). C1: ω = 2πf. C1: t = Δφ/ω. A1: t = 0.00341 s.', 3),
('754a2fba-1d34-5795-905c-7d5e04f0767f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 38, 38, 'A swing has natural angular frequency 2.1 rad s⁻¹. A child pushes it every 6.0 s. Calculate the swing''s natural period, and how many swings it makes between pushes. Give the number of swings.', NULL, 2, 'numeric'::answer_type, '2.005', NULL, false, 0.03, false, NULL, 'T = 2π ÷ 2.1 = 2.99 s. Swings between pushes = 6.0 ÷ 2.992 = 2.01: each push still lands at the same point of the cycle, so energy is still added. Mark scheme (4 marks). C1: T = 2π/ω. C1: ratio. B1: whole number of cycles. A1: swings = 2.01.', 4),
('57df8a42-19f3-5463-aaf9-1c06bb0361ce', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 39, 39, 'A hovering bee''s wings beat with angular frequency 1.4 × 10³ rad s⁻¹. Calculate the number of wing beats in 2.0 s.', NULL, 2, 'numeric'::answer_type, '445.6', NULL, false, 0.02, false, NULL, 'f = ω/2π = 1.4 × 10³ ÷ 2π = 223 Hz. N = ft = 222.8 × 2.0 = 446. Mark scheme (3 marks). C1: f = ω/2π. C1: N = ft. C1: substitution.', 3),
('2f893f44-5af3-5b3c-b797-e535fe24e675', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 40, 40, 'A small boat bobs with s.h.m. when a wave passes. The boat''s mass is 300 kg and the extra upthrust per metre of extra depth is 1.2 × 10⁴ N m⁻¹. (a) Calculate the angular frequency. (b) Calculate the period. (c) Explain why a heavier boat of the same shape bobs more slowly. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.9935', 's', false, NULL, false, NULL, '(a) ω = √(k/m) = √(1.2 × 10⁴ ÷ 300) = 6.32 rad s⁻¹. (b) T = 2π/ω = 2π ÷ 6.325 = 0.993 s. (c) Same k but larger m, so ω = √(k/m) is smaller and the period longer. Mark scheme (5 marks). C1: ω = √(k/m). A1: ω. C1: T = 2π/ω. A1: T = 0.993 s. B1: larger m, smaller ω.', 5),
('777fbd00-33d5-57ac-a08b-cbc5bf7153dc', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 41, 41, 'A student measures the period of a pendulum for two lengths: L = 0.50 m, T = 1.42 s; L = 1.50 m, T = 2.46 s. (a) Calculate ω for each. (b) Show that ω²L is approximately constant. (c) Use the mean value of ω²L to find g. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '9.787', 'N kg⁻¹', false, NULL, false, NULL, '(a) ω₁ = 2π ÷ 1.42 = 4.42 rad s⁻¹, ω₂ = 2π ÷ 2.46 = 2.55 rad s⁻¹. (b) ω₁²L₁ = 9.79, ω₂²L₂ = 9.79: nearly equal. (c) g = (9.789 + 9.785) ÷ 2 = 9.79 N kg⁻¹. Mark scheme (6 marks). C1: ω = 2π/T. A1: both ω. M1: ω²L for both. A1: approximately constant. C1: mean. A1: g = 9.79 N kg⁻¹.', 6),
('5bcddf33-8341-5490-b45c-8f73d0d790ce', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 42, 42, 'Two springs, each of constant 80 N m⁻¹, are joined end to end (in series) and support a 0.40 kg mass. In series the combined constant is half of one spring''s. (a) Calculate the combined spring constant. (b) Calculate ω. (c) Calculate the frequency and compare it with a single spring. Give only the frequency in (c).', NULL, 3, 'numeric'::answer_type, '1.592', 'Hz', false, NULL, false, NULL, '(a) k = 80 ÷ 2 = 40 N m⁻¹. (b) ω = √(40 ÷ 0.40) = 10 rad s⁻¹. (c) f = 10 ÷ 2π = 1.59 Hz; with one spring f = √(80 ÷ 0.40) ÷ 2π = 2.25 Hz, which is √2 times higher. Mark scheme (5 marks). A1: k = 40 N m⁻¹. C1: ω = √(k/m). A1: ω. C1: f = ω/2π. A1: f = 1.59 Hz.', 5),
('fbd1a919-40e6-5b37-896c-dbf7ca5db2fa', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 43, 43, 'A mass–spring system oscillates at 3.0 Hz. When an extra 0.10 kg is added the frequency falls to 2.5 Hz. (a) Show that m₁f₁² = m₂f₂² for the same spring. (b) Calculate the original mass. (c) Calculate the spring constant. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.2273', 'kg', false, NULL, false, NULL, '(a) f = (1/2π)√(k/m), so mf² = k/4π², a constant. (b) m × 3.0² = (m + 0.10) × 2.5², so m(9.0 − 6.25) = 0.625 and m = 0.625 ÷ 2.75 = 0.227 kg. (c) k = 4π²mf² = 4π² × 0.2273 × 3.0² = 80.8 N m⁻¹. Mark scheme (6 marks). M1: mf² constant. A1: shown. C1: equation in m. A1: m. C1: k = 4π²mf². A1: m = 0.227 kg.', 6),
('d656fa68-8120-52a1-ba54-30f35a539700', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 44, 44, 'A metronome''s arm behaves like a pendulum with an adjustable weight. At one setting it ticks 92 times per minute, one tick each half-swing. (a) Calculate the period of the arm. (b) Calculate ω. (c) The weight is moved so the period becomes 1.5 times longer. Calculate the new number of ticks per minute. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '61.33', NULL, false, NULL, false, NULL, '(a) 92 ticks = 46 oscillations per minute, T = 60 ÷ 46 = 1.30 s. (b) ω = 2π ÷ 1.304 = 4.82 rad s⁻¹. (c) A longer period means fewer ticks: 92 ÷ 1.5 = 61.3 ticks per minute. Mark scheme (5 marks). M1: two ticks per oscillation. A1: T. A1: ω. C1: ticks ∝ 1/T. A1: ticks = 61.3.', 5),
('0a1d93e6-9cf6-59c3-b3cb-93705cf67284', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 45, 45, 'In an atomic force microscope, a tiny cantilever of effective mass 2.5 × 10⁻¹¹ kg vibrates at 160 kHz. (a) Calculate ω. (b) Calculate the effective spring constant. (c) A particle of mass 1.0 × 10⁻¹⁵ kg sticks to it. Calculate the change in frequency. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3.2', 'Hz', false, NULL, false, NULL, '(a) ω = 2π × 1.60 × 10⁵ = 1.01 × 10⁶ rad s⁻¹. (b) k = mω² = 2.5 × 10⁻¹¹ × (1.01 × 10⁶)² = 25.3 N m⁻¹. (c) f ∝ 1/√m: new f = 1.60 × 10⁵ × √(2.5 × 10⁻¹¹ ÷ 2.5001 × 10⁻¹¹) = 1.59997 × 10⁵ Hz. The fall = 1.60 × 10⁵ × (1 − √(2.5 × 10⁻¹¹ ÷ 2.5001 × 10⁻¹¹)) = 3.20 Hz. Mark scheme (6 marks). C1: ω = 2πf. A1: ω. C1: k = mω². A1: k. C1: f ∝ 1/√m. A1: Δf = 3.2 Hz.', 6),
('8addad21-5e9d-52ec-b471-8c320152f195', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 46, 46, 'A pendulum clock''s pendulum has ω = 3.1416 rad s⁻¹ (period 2.000 s). (a) Calculate its length using g = 9.81 N kg⁻¹. (b) The length is increased by 1.0 mm. Calculate the new period. (c) Calculate how many seconds the clock loses per day. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '43.43', 's', false, NULL, false, NULL, '(a) L = g/ω² = 9.81 ÷ 3.1416² = 0.9940 m. (b) T = 2π × √(0.99496 ÷ 9.81) = 2.00101 s. (c) Seconds lost = 86400 × (1 − 2.000 ÷ 2.00101) = 43.4 s. Mark scheme (5 marks). C1: L = g/ω². A1: L. A1: new T. M1: fraction lost × 86 400. A1: loss = 43.4 s.', 5),
('bfd01a72-5b74-51af-af03-d16a0fa8c776', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 47, 47, 'A U-shaped tube holds water; the liquid column (length 0.40 m) oscillates with ω² = 2g/L. A second tube holds a column 0.90 m long. (a) Calculate ω for each. (b) Calculate the ratio of their periods. (c) Explain why changing the liquid to oil does not change ω. Give only the ratio (longer/shorter) in (b).', NULL, 3, 'numeric'::answer_type, '1.5', NULL, false, NULL, false, NULL, '(a) ω₁ = √(2 × 9.81 ÷ 0.40) = 7.00 rad s⁻¹, ω₂ = √(2 × 9.81 ÷ 0.90) = 4.67 rad s⁻¹. (b) T ∝ √L: ratio = √(0.90 ÷ 0.40) = 1.5. (c) Both the restoring force and the mass of liquid are proportional to its density, which cancels. Mark scheme (6 marks). C1: ω² = 2g/L. A1: both ω. C1: T ∝ √L. A1: ratio = 1.5. B1: density cancels. B1: reason.', 6),
('7a11c48b-1bb4-564f-be6e-c7bcb6b79f72', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 48, 48, 'A spring–mass system has ω = 8.0 rad s⁻¹. The spring is cut in half and the same mass hung from one half (each half has twice the spring constant). (a) Calculate the new ω. (b) Calculate the new period. (c) State the ratio of new frequency to old. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.5554', 's', false, NULL, false, NULL, '(a) ω ∝ √k: ω = 8.0 × √2 = 11.3 rad s⁻¹. (b) T = 2π ÷ 11.31 = 0.555 s. (c) √2 = 1.41. Mark scheme (5 marks). M1: k doubles. C1: ω ∝ √k. A1: ω. A1: T = 0.555 s. B1: √2.', 5),
('42d98f4e-b3de-5825-a2ae-f3e999346b6b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 49, 49, 'An astronaut finds that a 1.00 kg mass on a spring oscillates at 1.25 Hz on Earth and also at 1.25 Hz on a moon, while a 1.00 m pendulum has ω = 3.13 rad s⁻¹ on Earth and 1.42 rad s⁻¹ on the moon. (a) Explain why the spring frequency is the same in both places. (b) Calculate g on the moon. (c) Calculate the spring constant. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.016', 'N kg⁻¹', false, NULL, false, NULL, '(a) ω = √(k/m) has no g in it. (b) ω² = g/L: g = ω²L = 1.42² × 1.00 = 2.02 N kg⁻¹. (c) k = m(2πf)² = 1.00 × (2π × 1.25)² = 61.7 N m⁻¹. Mark scheme (6 marks). B1: no g in spring ω. C1: g = ω²L. A1: g. C1: k = mω². C1: ω = 2πf. A1: g = 2.02 N kg⁻¹.', 6),
('f58501e6-73f5-5bce-bbe5-0e44bf03603b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '229f2746-5b87-4ef8-b289-1403198687fc', 'a-level', '18.6', '9702 coursebook 18.6 · Frequency and angular frequency', 50, 50, 'A tall chimney sways with period 2.2 s. An engineer fits a damper and the effective mass doubles while the stiffness rises by 50 %. (a) Calculate the original ω. (b) Calculate the new ω. (c) Calculate the new period. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.54', 's', false, NULL, false, NULL, '(a) ω = 2π ÷ 2.2 = 2.86 rad s⁻¹. (b) ω ∝ √(k/m): ω = 2.86 × √(1.5 ÷ 2) = 2.47 rad s⁻¹. (c) T = 2π ÷ 2.473 = 2.54 s. Mark scheme (5 marks). C1: ω = 2π/T. A1: original ω. C1: ω ∝ √(k/m). A1: new ω. A1: T = 2.54 s.', 5)
