('c5560fb4-579c-5947-be97-3aef7de04395', '987e561c-6d9e-5cb1-a192-a1f990f2b144', 'ω = 2πf; 2π/f has the wrong unit (rad s, not rad s⁻¹)', 'B', true, 1),
('91f0f70d-cc1a-5f4d-990d-c0d90125a440', '987e561c-6d9e-5cb1-a192-a1f990f2b144', 'ω = f/2π', 'C', false, 2),
