('80ac6d80-c405-5a47-b185-3813f18fd39e', '5fb66fc0-d847-56d2-b011-caad6ddc4ea9', '4.1 rad s⁻¹', 'A', false, 0),
('c43eb7d1-a06a-5a6c-a2d3-2219cada9d1e', '5fb66fc0-d847-56d2-b011-caad6ddc4ea9', '24 rad s⁻¹', 'B', false, 1),
('0ffbdc53-6e16-592e-882c-1907b80b1a26', '5fb66fc0-d847-56d2-b011-caad6ddc4ea9', '10 rad s⁻¹', 'C', true, 2),
('91505d59-cef3-5f65-ac1e-27185f2360f2', '5fb66fc0-d847-56d2-b011-caad6ddc4ea9', '1.6 rad s⁻¹', 'D', false, 3),
('2b79ecec-3172-517e-bee5-0207f5849b80', '5b0f04da-8eea-5cac-bc2d-637f2002c292', 'B oscillates with twice the angular frequency of A', 'A', true, 0),
