('cdd07d66-4b89-5393-8cdb-87613a06b60c', '5b0f04da-8eea-5cac-bc2d-637f2002c292', 'A oscillates with twice the angular frequency of B', 'C', false, 2),
('7a06111c-68b3-52a3-bcd9-ce2183d48b5f', '5b0f04da-8eea-5cac-bc2d-637f2002c292', 'Both have the same angular frequency', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('fe8518f8-df8a-51cd-9280-94311b99d3a9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 7, 7, 'An oscillator obeys x = 0.030 cos(20t) m. Calculate its displacement at t = 0.', NULL, 1, 'numeric'::answer_type, '0.03', 'm', false, NULL, false, NULL, 'At t = 0, cos 0 = 1, so x = 0.030 × 1 = 0.030 m. Mark scheme (2 marks). C1: substitute t = 0. A1: x = 0.030 m.', 2),
('cdece2b8-129b-5bc3-a483-6ec35f2b0221', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 8, 8, 'An oscillator obeys x = 0.050 sin(10t) m. Calculate its maximum speed.', NULL, 1, 'numeric'::answer_type, '0.5', 'm s⁻¹', false, NULL, false, NULL, 'v_max = ωx₀ = 10 × 0.050 = 0.50 m s⁻¹. Mark scheme (2 marks). C1: v_max = ωx₀. A1: v_max = 0.50 m s⁻¹.', 2),
('7b25e376-0d79-53ea-a9e4-a8156b675c9d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 9, 9, 'An object starts from its equilibrium position at t = 0 and oscillates with amplitude x₀. Which equation describes its displacement?', NULL, 1, 'multiple_choice'::answer_type, 'x = x₀ sin ωt', NULL, false, NULL, false, NULL, 'sin 0 = 0, so x = x₀ sin ωt starts at equilibrium. Mark scheme (1 mark). B1: C (x = x₀ sin ωt).', 1),
('b3054917-d0fa-5ae4-a6b0-206a267640a8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 10, 10, 'Which equation gives the speed of an s.h.m. object at displacement x?', NULL, 1, 'multiple_choice'::answer_type, 'v = ω√(x₀² − x²)', NULL, false, NULL, false, NULL, 'From energy or calculus: v² = ω²(x₀² − x²). Mark scheme (1 mark). B1: A (v = ω√(x₀² − x²)).', 1),
('02a7fd01-be1f-5c0c-9bd8-815209b10ed4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 11, 11, 'For x = 0.040 sin(6.0t) m, calculate the maximum acceleration.', NULL, 1, 'numeric'::answer_type, '1.44', 'm s⁻²', false, NULL, false, NULL, 'a_max = ω²x₀ = 6.0² × 0.040 = 1.44 m s⁻². Mark scheme (2 marks). C1: a_max = ω²x₀. A1: a_max = 1.44 m s⁻².', 2),
('c1f64eec-8fac-506e-983a-bd6e6617a903', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 12, 12, 'An s.h.m. has ω = 5.0 rad s⁻¹ and amplitude 0.10 m. Calculate its speed when x = 0.060 m.', NULL, 1, 'numeric'::answer_type, '0.4', 'm s⁻¹', false, NULL, false, NULL, 'v = ω√(x₀² − x²) = 5.0 × √(0.10² − 0.060²) = 0.40 m s⁻¹. Mark scheme (2 marks). C1: v = ω√(x₀² − x²). A1: v = 0.40 m s⁻¹.', 2),
('957a4554-d2c9-55f2-a604-422854782875', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 13, 13, 'For x = x₀ cos ωt, which equation gives the velocity?', NULL, 1, 'multiple_choice'::answer_type, 'v = −ωx₀ sin ωt', NULL, false, NULL, false, NULL, 'v = dx/dt = −ωx₀ sin ωt. Mark scheme (1 mark). B1: D (v = −ωx₀ sin ωt).', 1),
('11431020-2940-5f57-b853-bc59909ce652', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 14, 14, 'An oscillator obeys x = 0.025 sin(4πt) m. Calculate its frequency.', NULL, 1, 'numeric'::answer_type, '2', 'Hz', false, NULL, false, NULL, 'ω = 4π rad s⁻¹, so f = ω/2π = 4π ÷ 2π = 2.0 Hz. Mark scheme (2 marks). C1: f = ω/2π. A1: f = 2.0 Hz.', 2),
('707a2520-0868-5164-9c33-5cb9dc53a5e5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 15, 15, 'For x = 0.080 cos(2.5t) m, what is the period?', NULL, 1, 'numeric'::answer_type, '2.513', 's', false, NULL, false, NULL, 'T = 2π/ω = 2π ÷ 2.5 = 2.51 s. Mark scheme (2 marks). C1: T = 2π/ω. A1: T = 2.51 s.', 2),
('3cd19f85-b356-597b-83b4-a42d82fcf4c4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 16, 16, 'In x = x₀ sin ωt, what does x₀ represent?', NULL, 1, 'multiple_choice'::answer_type, 'The amplitude', NULL, false, NULL, false, NULL, 'x₀ is the maximum value of x, reached when sin ωt = ±1. Mark scheme (1 mark). B1: B (The amplitude).', 1),
('7c01f1e9-7c16-53a1-ad89-168e69c5dd1a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 17, 17, 'An object in s.h.m. has amplitude 0.20 m and ω = 3.0 rad s⁻¹. Calculate its speed at the equilibrium position.', NULL, 1, 'numeric'::answer_type, '0.6', 'm s⁻¹', false, NULL, false, NULL, 'At x = 0, v = ωx₀ = 3.0 × 0.20 = 0.60 m s⁻¹. Mark scheme (2 marks). C1: v = ωx₀ at x = 0. A1: v = 0.60 m s⁻¹.', 2),
('e6251d60-f150-5def-b528-3c41caaa7ccf', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 18, 18, 'For a = −ω²x with ω = 7.0 rad s⁻¹, calculate the acceleration at x = −0.020 m.', NULL, 1, 'numeric'::answer_type, '0.98', 'm s⁻²', false, NULL, true, NULL, 'a = −ω²x = −49 × (−0.020) = +0.98 m s⁻². Mark scheme (2 marks). C1: a = −ω²x with sign. A1: a = 0.980 m s⁻².', 2),
('c53d6a99-6010-5b85-9815-e3d9aeabfa17', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 19, 19, 'An oscillator obeys x = 0.10 cos(πt) m. Where is it at t = 1.0 s?', NULL, 1, 'multiple_choice'::answer_type, 'At x = −0.10 m', NULL, false, NULL, false, NULL, 'cos(π) = −1, so x = −0.10 m: the opposite extreme. Mark scheme (1 mark). B1: C (At x = −0.10 m).', 1),
('4b46b5d3-aa3d-5600-9f64-e089105976db', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 20, 20, 'An s.h.m. obeys x = x₀ sin ωt. At what time does it first reach its maximum displacement?', NULL, 1, 'multiple_choice'::answer_type, 't = π/(2ω)', NULL, false, NULL, false, NULL, 'sin ωt = 1 first when ωt = π/2, so t = π/(2ω) — a quarter period. Mark scheme (1 mark). B1: A (t = π/(2ω)).', 1),
('b3d68fcc-3f45-5636-8115-89cd9e84b12d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 21, 21, 'An oscillator obeys v = 0.12 cos(8.0t) m s⁻¹. Calculate its amplitude.', NULL, 1, 'numeric'::answer_type, '0.015', 'm', false, NULL, false, NULL, 'v_max = ωx₀, so x₀ = 0.12 ÷ 8.0 = 0.015 m. Mark scheme (2 marks). C1: x₀ = v_max/ω. A1: x₀ = 0.015 m.', 2),
('813938ec-c34b-5db2-bbf3-630c1caea86c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 22, 22, 'A playground spring-rider rocks back and forth with s.h.m.: ω = 2.0 rad s⁻¹, amplitude 0.50 m. How fast is the seat moving when it is 0.30 m from its central position?', NULL, 1, 'numeric'::answer_type, '0.8', 'm s⁻¹', false, NULL, false, NULL, 'v = ω√(x₀² − x²) = 2.0 × √(0.50² − 0.30²) = 0.80 m s⁻¹. Mark scheme (2 marks). C1: v = ω√(x₀² − x²). A1: v = 0.80 m s⁻¹.', 2),
('4bf85bcf-ef14-57dd-8b3c-b912f28a3f55', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 23, 23, 'Which equation is NOT correct for s.h.m.?', NULL, 1, 'multiple_choice'::answer_type, 'v = ω²x', NULL, false, NULL, false, NULL, 'v = ω²x is wrong: the speed is v = ω√(x₀² − x²), maximum ωx₀. Mark scheme (1 mark). B1: D (v = ω²x).', 1),
('2cf78ad1-e07d-58f1-95b8-3d8b1f4f8788', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 24, 24, 'An oscillator obeys x = 0.060 sin(5.0t) m. Calculate x at t = 0.10 s.', NULL, 1, 'numeric'::answer_type, '0.02877', 'm', false, NULL, false, NULL, 'ωt = 0.50 rad = 28.6°. x = 0.060 × sin 28.6° = 0.0288 m. Mark scheme (2 marks). C1: ωt in radians. A1: x = 0.0288 m.', 2),
('b706023a-a77d-5bf1-9072-3e4a3fb0177c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 25, 25, 'A body moves with x = 0.15 cos(3.0t) m. Calculate its displacement, velocity and acceleration at t = 0.40 s. Give the velocity.', NULL, 2, 'numeric'::answer_type, '-0.4194', 'm s⁻¹', false, NULL, true, NULL, 'ωt = 1.2 rad = 68.75°. x = 0.15 × cos 68.75° = 0.0544 m. v = −0.15 × 3.0 × sin 68.75° = −0.419 m s⁻¹. a = −ω²x = −9.0 × 0.0544 = −0.489 m s⁻². Mark scheme (3 marks). C1: ωt in radians. C1: v = −ωx₀ sin ωt. C1: substitution.', 3),
('58f855fe-f924-5247-baf5-cf4517485b8a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 26, 26, 'An oscillator released from rest at x = +4.0 cm has period 1.6 s. Find the first time after release at which x = +2.0 cm.', NULL, 2, 'numeric'::answer_type, '0.2667', 's', false, NULL, false, NULL, 'x = x₀ cos ωt: cos ωt = 0.5 gives ωt = π/3. ω = 2π ÷ 1.6, so t = (π/3) ÷ (2π ÷ 1.6) = 1.6 ÷ 6 = 0.267 s. Mark scheme (3 marks). C1: x = x₀ cos ωt. C1: ωt = π/3. C1: t = (π/3)/ω.', 3),
('f0f9173e-284b-574a-af3d-70e393e83df4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 27, 27, 'An s.h.m. has x = 0.040 sin(ωt) m with period 0.80 s. Calculate the speed at t = 0.10 s.', NULL, 2, 'numeric'::answer_type, '0.2221', 'm s⁻¹', false, NULL, false, NULL, 'ω = 2π ÷ 0.80 = 7.85 rad s⁻¹. ωt = π/4 rad = 45°. v = ωx₀ cos ωt = 7.85 × 0.040 × cos 45° = 0.222 m s⁻¹. Mark scheme (4 marks). C1: ω = 2π/T. C1: v = ωx₀ cos ωt. C1: ωt = 45°. A1: v = 0.222 m s⁻¹.', 4),
('ad5034e8-64ac-56b8-a463-449be390559e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 28, 28, 'An s.h.m. obeys x = x₀ sin ωt. At what displacement is the speed equal to half the maximum speed?', NULL, 2, 'multiple_choice'::answer_type, '±(√3/2)x₀', NULL, false, NULL, false, NULL, 'v = ω√(x₀² − x²) = ωx₀/2 gives x² = ¾x₀². Mark scheme (3 marks). C1: v expression. C1: solve. A1: B (±(√3/2)x₀).', 3),
('d1827aff-cd42-5e43-9a21-1eafbb6bed01', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 29, 29, 'An oscillator has v_max = 0.30 m s⁻¹ and ω = 6.0 rad s⁻¹. Calculate its speed at a displacement of 4.0 cm.', NULL, 2, 'numeric'::answer_type, '0.18', 'm s⁻¹', false, NULL, false, NULL, 'x₀ = v_max/ω = 0.30 ÷ 6.0 = 0.050 m. v = ω√(x₀² − x²) = 6.0 × √(0.050² − 0.040²) = 0.180 m s⁻¹. Mark scheme (3 marks). C1: x₀ = v_max/ω. C1: v formula. C1: substitution.', 3),
('73ad3b64-80cb-54d4-86a4-5657ce02bdca', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 30, 30, 'A mass oscillates with x = 0.12 sin(2πft) m and f = 0.50 Hz. Calculate how long it takes to move from x = 0 to x = 0.060 m.', NULL, 2, 'numeric'::answer_type, '0.1667', 's', false, NULL, false, NULL, 'sin(2πft) = 0.060 ÷ 0.12 = 0.50, so 2πft = π/6 and t = (π/6) ÷ (2π × 0.50) = 0.167 s. Mark scheme (4 marks). C1: sin ωt = 0.5. C1: ωt = π/6. C1: t. A1: t = 0.167 s.', 4),
('b8dbf41e-f472-5bcf-b5a9-67c7d72f37cd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 31, 31, 'For x = 0.20 cos(5t) m, at which first time after t = 0 is the object at equilibrium?', NULL, 2, 'multiple_choice'::answer_type, 'π/10 s', NULL, false, NULL, false, NULL, 'cos 5t = 0 first at 5t = π/2, so t = π/10 s ≈ 0.31 s. Mark scheme (3 marks). C1: cos = 0. C1: 5t = π/2. A1: C (π/10 s).', 3),
('274b9a43-4a63-50fb-b0f2-f7378b154358', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 32, 32, 'An oscillator obeys a = −0.80 sin(4.0t) m s⁻². Calculate the displacement at t = 0.25 s.', NULL, 2, 'numeric'::answer_type, '0.04207', 'm', false, NULL, false, NULL, 'a = −ω²x, so x = (0.80 ÷ 4.0²) sin(4.0t) = 0.050 sin(4.0t) m. At t = 0.25 s, 4.0t = 1.0 rad = 57.3°: x = 0.050 × sin 57.3° = 0.0421 m. Mark scheme (3 marks). C1: x₀ = a_max/ω². C1: x expression. C1: substitution in radians.', 3),
('fbd96717-c400-5764-98a0-bf9afa738de9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 33, 33, 'A pendulum of length 0.75 m is released from 5.0 cm to one side. Write an equation for its displacement and use it to find x at t = 0.30 s. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.02335', 'm', false, NULL, false, NULL, 'ω = √(g/L) = √(9.81 ÷ 0.75) = 3.62 rad s⁻¹. x = 0.050 cos(ωt). ωt = 1.08 rad = 62.2°: x = 0.050 × cos 62.2° = 0.0233 m. Mark scheme (4 marks). C1: ω = √(g/L). C1: x = x₀ cos ωt (released from rest). C1: substitution. A1: x = 0.0233 m.', 4),
('30ce32c3-3ff1-5feb-a160-466ed7dd64f2', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 34, 34, 'Which pair of equations describes an oscillator that starts at x = 0 moving in the negative direction?', NULL, 2, 'multiple_choice'::answer_type, 'x = −x₀ sin ωt and v = −ωx₀ cos ωt', NULL, false, NULL, false, NULL, 'At t = 0: x = 0, v = −ωx₀ (negative, maximum). Only the first pair gives this. Mark scheme (4 marks). C1: x = 0 at t = 0. C1: v negative at t = 0. C1: consistent derivative. A1: A (x = −x₀ sin ωt and v = −ωx₀ cos ωt).', 4),
('c8940289-c511-5dab-8e0f-145514068b86', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 35, 35, 'For s.h.m. with amplitude 6.0 cm, at what displacement is the speed 80 % of the maximum?', NULL, 2, 'numeric'::answer_type, '0.036', 'm', false, NULL, false, NULL, 'v/v_max = √(1 − x²/x₀²) = 0.80, so x = x₀√(1 − 0.64) = 0.060 × 0.60 = 0.036 m. Mark scheme (3 marks). C1: v/v_max = √(1 − x²/x₀²). C1: solve. A1: x = 0.036 m.', 3),
('d82ca5e9-55e0-5b8c-b479-483bd2295f72', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 36, 36, 'A mass on a spring oscillates with x = 0.050 cos(12t) m. Calculate the time taken to move from x = +0.050 m to x = −0.025 m.', NULL, 2, 'numeric'::answer_type, '0.1745', 's', false, NULL, false, NULL, 'cos 12t = −0.025 ÷ 0.050 = −0.50, so 12t = 2π/3 and t = (2π/3) ÷ 12 = 0.175 s. Mark scheme (4 marks). C1: cos 12t = −0.5. C1: 12t = 2π/3. C1: t. A1: t = 0.175 s.', 4),
('dc7bc0d3-aea9-51ed-b47b-1a8f94208730', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 37, 37, 'An oscillator is at x = +x₀ at t = 0. Which equation gives its acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'a = −ω²x₀ cos ωt', NULL, false, NULL, false, NULL, 'x = x₀ cos ωt, so a = −ω²x = −ω²x₀ cos ωt (negative maximum at t = 0). Mark scheme (3 marks). C1: x = x₀ cos ωt. C1: a = −ω²x. A1: D (a = −ω²x₀ cos ωt).', 3),
('837220a8-48e2-5e27-a475-7eb54fbd084c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 38, 38, 'An oscillator obeys x = 0.090 sin(15t) m. Calculate its speed at x = 0.054 m.', NULL, 2, 'numeric'::answer_type, '1.08', 'm s⁻¹', false, NULL, false, NULL, 'v = ω√(x₀² − x²) = 15 × √(0.090² − 0.054²) = 15 × 0.072 = 1.08 m s⁻¹. Mark scheme (3 marks). C1: ω and x₀ read from equation. C1: v formula. A1: v = 1.08 m s⁻¹.', 3),
('a18355ff-7e40-5dde-abd9-49c15e59bd4d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 39, 39, 'A body in s.h.m. passes through equilibrium at 0.60 m s⁻¹ and has period 1.2 s. Write an equation for x and calculate x at t = 0.20 s after passing through equilibrium.', NULL, 2, 'numeric'::answer_type, '0.09924', 'm', false, NULL, false, NULL, 'ω = 2π ÷ 1.2 = 5.24 rad s⁻¹, x₀ = 0.60 ÷ ω = 0.115 m. x = x₀ sin ωt. ωt = π/3 rad = 60°: x = 0.1146 × sin 60° = 0.0992 m. Mark scheme (4 marks). C1: x₀ = v_max/ω. C1: x = x₀ sin ωt. C1: substitution. A1: x = 0.0992 m.', 4),
('0944c794-da4b-58b1-a39e-12aa155e158f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 40, 40, 'For s.h.m., which graph of v² against x² is a straight line?', NULL, 2, 'multiple_choice'::answer_type, 'One with negative gradient −ω² and intercept ω²x₀²', NULL, false, NULL, false, NULL, 'v² = ω²x₀² − ω²x²: linear in x² with gradient −ω². Mark scheme (3 marks). C1: v² = ω²(x₀² − x²). C1: negative gradient. A1: B (One with negative gradient −ω² and intercept ω²x₀²).', 3),
('b064cc32-2b6f-5f88-8460-bf972feaf142', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 41, 41, 'A graph of v² against x² for an oscillator is a straight line from (0, 0.36 m² s⁻²) to (0.0025 m², 0). Calculate ω and the amplitude. Give ω.', NULL, 2, 'numeric'::answer_type, '12', 'rad s⁻¹', false, NULL, false, NULL, 'Gradient = −0.36 ÷ 0.0025 = −144 s⁻², which is −ω², so ω = √144 = 12 rad s⁻¹. x₀² = 0.0025 m², x₀ = 0.050 m. Mark scheme (3 marks). C1: gradient = −ω². C1: x-intercept = x₀². A1: ω = 12 rad s⁻¹.', 3),
('2293510e-ed61-57bd-91df-7ce1cd233a4f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 42, 42, 'An oscillator has period 0.50 s and amplitude 3.0 cm. Calculate its acceleration 0.050 s after passing through +x₀.', NULL, 2, 'numeric'::answer_type, '-3.833', 'm s⁻²', false, NULL, true, NULL, 'x = x₀ cos ωt with ω = 4π rad s⁻¹. ωt = 0.2π rad = 36°. a = −ω²x₀ cos ωt = −(4π)² × 0.030 × cos 36° = −3.83 m s⁻². Mark scheme (3 marks). C1: x = x₀ cos ωt. C1: a = −ω²x. C1: substitution.', 3),
('09f8469a-4e31-596d-9d27-4082bd12182e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 43, 43, 'A 0.25 kg mass oscillates on a spring with x = 0.080 cos(10t) m. (a) Calculate the spring constant. (b) Calculate the speed at t = 0.12 s. (c) Calculate the resultant force on the mass at that instant. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '-0.7247', 'N', false, NULL, true, NULL, '(a) k = mω² = 0.25 × 10² = 25 N m⁻¹. (b) ωt = 1.2 rad = 68.75°: v = 10 × 0.080 × sin 68.75° = 0.746 m s⁻¹. (c) x = 0.080 × cos 68.75° = 0.0290 m, F = −kx = −25 × 0.0290 = −0.725 N. Mark scheme (6 marks). C1: k = mω². A1: k. C1: speed at t. A1: v. C1: F = −kx. A1: F = −0.725 N.', 6),
('a434d6c9-7439-577a-abce-3d47f0485dd8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 44, 44, 'An object performs s.h.m. of period 2.0 s and amplitude 10 cm, starting at x = 0 at t = 0. (a) Write x(t). (b) Calculate the time taken to go from x = 0 to x = 5.0 cm. (c) Calculate the time taken to go from x = 5.0 cm to x = 10 cm, and explain why it is longer. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.3333', 's', false, NULL, false, NULL, '(a) x = 0.10 sin(πt) m. (b) sin(πt) = 0.5: πt = π/6, t = 1/6 = 0.167 s. (c) 0 to 10 cm takes T/4 = 0.50 s, so 5 to 10 cm takes 0.50 − 0.167 = 0.333 s: the object slows as it approaches the extreme. Mark scheme (5 marks). B1: x = 0.10 sin πt. C1: sin πt = 0.5. A1: 0.167 s. C1: T/4 − 0.167. A1: 0.333 s and reason.', 5),
('b95bfbf1-6eef-5190-9ccd-c40de5db438b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 45, 45, 'A mass on a spring has a = −64x (SI units). It is released from rest at x = 0.050 m. (a) Calculate ω and the period. (b) Calculate the speed when x = 0.030 m. (c) Calculate the time taken to reach x = 0.030 m for the first time. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.1159', 's', false, NULL, false, NULL, '(a) ω = 8.0 rad s⁻¹, T = 2π ÷ 8.0 = 0.785 s. (b) v = 8.0 × √(0.050² − 0.030²) = 0.32 m s⁻¹. (c) x = 0.050 cos 8t: cos 8t = 0.60, 8t = cos⁻¹ 0.60 = 53.13° = 0.927 rad, t = 0.927 ÷ 8.0 = 0.116 s. Mark scheme (6 marks). A1: ω and T. C1: v = ω√(x₀² − x²). A1: v. C1: cos 8t = 0.6. C1: inverse cosine in radians. A1: t = 0.116 s.', 6),
('25d632de-0f29-5a07-80e2-9e67f612dbf2', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 46, 46, 'Derive v = ±ω√(x₀² − x²) from x = x₀ sin ωt and v = ωx₀ cos ωt, then use it. (a) Show the derivation. (b) For x₀ = 0.20 m and ω = 4.0 rad s⁻¹, find the speed at x = 0.12 m. (c) Find the two times in the first cycle at which x = +0.12 m. Give only the speed in (b).', NULL, 3, 'numeric'::answer_type, '0.64', 'm s⁻¹', false, NULL, false, NULL, '(a) cos ωt = ±√(1 − sin²ωt) = ±√(1 − x²/x₀²), so v = ±ωx₀√(1 − x²/x₀²) = ±ω√(x₀² − x²). (b) v = 4.0 × √(0.20² − 0.12²) = 0.64 m s⁻¹. (c) sin 4t = 0.60: 4t = 0.6435 rad or π − 0.6435 rad, so t = 0.161 s or 0.625 s. Mark scheme (5 marks). M1: sin² + cos² = 1. A1: derivation. C1: substitution. A1: v = 0.64 m s⁻¹. B1: both times.', 5),
('cc3b2b67-81fd-5795-96dd-1c12df0e4ca8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 47, 47, 'A buoy moves up and down with s.h.m. as waves pass: amplitude 0.60 m, period 5.0 s. A sensor on the buoy can only work when the buoy is at least 0.30 m above its mean level. (a) Write y(t), with y = 0 rising at t = 0. (b) Find the times in the first cycle when y = 0.30 m. (c) Calculate the time per cycle that the sensor works. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.667', 's', false, NULL, false, NULL, '(a) y = 0.60 sin(2πt/5.0) m. (b) sin(2πt/5) = 0.5 at 2πt/5 = π/6 and 5π/6: t = 0.417 s and 2.08 s. (c) working time = 2.08 − 0.417 = 1.67 s per cycle (one third of the period). Mark scheme (6 marks). B1: y = 0.60 sin(2πt/5). C1: sin = 0.5. A1: both times. M1: difference. A1: t = 1.67 s. B1: fraction of period.', 6),
('e5ed012f-3d33-5f19-bf62-29a1b26073ce', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 48, 48, 'An oscillator has displacement x = 0.10 sin(2.0t) + 0.10 cos(2.0t) m. (a) Show that this is s.h.m. with ω = 2.0 rad s⁻¹ by finding a. (b) Show that the amplitude is 0.10√2 m. (c) Calculate the maximum speed. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.2828', 'm s⁻¹', false, NULL, false, NULL, '(a) a = −4.0 × (0.10 sin 2t + 0.10 cos 2t) = −4.0x, so a = −ω²x with ω = 2.0 rad s⁻¹. (b) The sum equals 0.10√2 sin(2t + π/4), so x₀ = 0.10 × √2 = 0.141 m. (c) v_max = ωx₀ = 2.0 × 0.1414 = 0.283 m s⁻¹. Mark scheme (5 marks). M1: second derivative. A1: a = −4x. B1: amplitude √2 × 0.10. C1: v_max = ωx₀. A1: v_max = 0.283 m s⁻¹.', 5),
('e6005c39-a05c-5107-b4d8-228c8047699a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 49, 49, 'A trolley between springs oscillates with x = 0.060 sin(3.0t) m. (a) State x₀ and ω. (b) Calculate the time from t = 0 at which the trolley first has a speed of 0.090 m s⁻¹. (c) Calculate its displacement at that moment. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.3491', 's', false, NULL, false, NULL, '(a) x₀ = 0.060 m, ω = 3.0 rad s⁻¹. (b) v = ωx₀ cos ωt = 0.18 cos 3.0t = 0.090, so cos 3.0t = 0.50, 3.0t = cos⁻¹ 0.50 = 60°, which is π/3 rad, and t = (π/3) ÷ 3.0 = 0.349 s. (c) x = 0.060 × sin 60° = 0.0520 m. Mark scheme (5 marks). B1: x₀ and ω. C1: v = ωx₀ cos ωt. C1: cos 3t = 0.5. A1: t = 0.349 s. B1: x.', 5),
('23764c0e-51cf-5e47-8624-09286d51201f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '636093e8-e743-4275-b678-97f3624e39a0', 'a-level', '18.7', '9702 coursebook 18.7 · Equations of s.h.m.', 50, 50, 'A mass oscillating with s.h.m. passes x = 2.0 cm with speed 0.30 m s⁻¹ and x = 4.0 cm with speed 0.20 m s⁻¹. (a) Use v² = ω²(x₀² − x²) to find ω. (b) Find the amplitude. (c) Find the maximum acceleration. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.108', 'm s⁻²', false, NULL, false, NULL, '(a) 0.30² − 0.20² = ω²(0.040² − 0.020²): 0.050 = ω² × 0.0012, ω² = 41.7 s⁻², ω = 6.45 rad s⁻¹. (b) x₀² = 0.020² + 0.30² ÷ ω² = 0.0004 + 0.09 ÷ 41.67 = 0.00256 m², x₀ = 0.0506 m. (c) a_max = ω²x₀ = 41.67 × 0.05060 = 2.11 m s⁻². Mark scheme (6 marks). M1: subtract the two equations. A1: ω. C1: x₀² from one equation. A1: x₀. C1: a_max = ω²x₀. A1: a_max = 2.11 m s⁻².', 6)
