('db0935b2-f596-556a-bdc7-3458e920b2be', 'dc7bc0d3-aea9-51ed-b47b-1a8f94208730', 'a = ωx₀ cos ωt', 'C', false, 2),
('9cae7cb7-3752-5a6d-9929-32a24d3c0959', 'dc7bc0d3-aea9-51ed-b47b-1a8f94208730', 'a = −ω²x₀ cos ωt', 'D', true, 3),
('ddd96591-3fc0-5767-a70a-5ad16b032bc6', '0944c794-da4b-58b1-a39e-12aa155e158f', 'One through the origin with gradient ω²', 'A', false, 0),
('b338cfcb-faa4-5423-af87-ce47c2d41e52', '0944c794-da4b-58b1-a39e-12aa155e158f', 'One with negative gradient −ω² and intercept ω²x₀²', 'B', true, 1),
('49bcd9e8-1b7a-5ffb-928a-813012f27db2', '0944c794-da4b-58b1-a39e-12aa155e158f', 'A horizontal line', 'C', false, 2),
('222f1a20-3e7a-5201-ac37-58625447cf43', '0944c794-da4b-58b1-a39e-12aa155e158f', 'One with positive gradient ω²', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('cd8c163c-7c80-50e8-945b-188c359f8537', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 9, 9, 'A 0.40 kg mass oscillates with ω = 5.0 rad s⁻¹ and amplitude 0.10 m. Calculate its total energy.', NULL, 1, 'numeric'::answer_type, '0.05', 'J', false, NULL, false, NULL, 'E = ½mω²x₀² = 0.5 × 0.40 × 5.0² × 0.10² = 0.050 J. Mark scheme (2 marks). C1: E = ½mω²x₀². A1: E = 0.050 J.', 2),
('42cbd378-4f11-5956-9e41-bd4c767d02be', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 10, 10, 'A 2.0 kg mass oscillating with s.h.m. has a maximum speed of 0.30 m s⁻¹. Calculate its maximum kinetic energy.', NULL, 1, 'numeric'::answer_type, '0.09', 'J', false, NULL, false, NULL, 'Ek = ½mv_max² = 0.5 × 2.0 × 0.30² = 0.090 J. Mark scheme (2 marks). C1: Ek = ½mv². A1: Ek = 0.090 J.', 2),
('55172ff0-8839-5ca1-99c8-11e8e7a3ff5b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 11, 11, 'In s.h.m., where is the potential energy (for a spring) greatest?', NULL, 1, 'multiple_choice'::answer_type, 'At maximum displacement', NULL, false, NULL, false, NULL, 'Ep = ½kx² is greatest at x = ±x₀, where the speed (and Ek) is zero. Mark scheme (1 mark). B1: C (At maximum displacement).', 1),
('6dae9b4c-9b54-5be6-83b0-ff0f29fafca2', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 12, 12, 'For an undamped oscillator, how does the total energy change during one cycle?', NULL, 1, 'multiple_choice'::answer_type, 'It stays constant', NULL, false, NULL, false, NULL, 'Energy is transferred between Ek and Ep, but with no damping the total stays constant. Mark scheme (1 mark). B1: A (It stays constant).', 1),
('6c35a981-e6ab-536b-b656-a5b3c37f80ec', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 13, 13, 'The amplitude of an oscillator is tripled at the same frequency. By what factor does its total energy change?', NULL, 1, 'multiple_choice'::answer_type, '9', NULL, false, NULL, false, NULL, 'E = ½mω²x₀² ∝ x₀²: 3² = 9. Mark scheme (1 mark). B1: D (9).', 1),
('7311ba57-9a36-51b8-9842-374c06c85d01', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 14, 14, 'A spring of constant 50 N m⁻¹ is stretched 0.12 m from equilibrium in an oscillation. Calculate the elastic potential energy there.', NULL, 1, 'numeric'::answer_type, '0.36', 'J', false, NULL, false, NULL, 'Ep = ½kx² = 0.5 × 50 × 0.12² = 0.36 J. Mark scheme (2 marks). C1: Ep = ½kx². A1: Ep = 0.36 J.', 2),
('8b1dce6e-5623-55ed-93d6-ecaac034f725', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 15, 15, 'An oscillator has total energy 0.80 J. At one instant its kinetic energy is 0.30 J. Calculate its potential energy.', NULL, 1, 'numeric'::answer_type, '0.5', 'J', false, NULL, false, NULL, 'Ep = E − Ek = 0.80 − 0.30 = 0.50 J. Mark scheme (2 marks). C1: E = Ek + Ep. A1: Ep = 0.50 J.', 2),
('4d52fad8-49cf-5eed-bdc4-c18fc34ff59b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 16, 16, 'At what displacement in s.h.m. are the kinetic and potential energies equal?', NULL, 1, 'multiple_choice'::answer_type, 'x = ±x₀/√2', NULL, false, NULL, false, NULL, 'Ep = ½mω²x² equals half the total ½mω²x₀² when x² = x₀²/2. Mark scheme (1 mark). B1: B (x = ±x₀/√2).', 1),
('2030e5dd-0317-5774-8016-493d2348598a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 17, 17, 'A 0.050 kg mass on a spring has total energy 2.0 × 10⁻³ J. Calculate its maximum speed.', NULL, 1, 'numeric'::answer_type, '0.2828', 'm s⁻¹', false, NULL, false, NULL, 'At equilibrium all energy is kinetic: v = √(2E/m) = √(2 × 2.0 × 10⁻³ ÷ 0.050) = 0.283 m s⁻¹. Mark scheme (2 marks). C1: E = ½mv_max². A1: v_max = 0.283 m s⁻¹.', 2),
('9961c177-843c-516c-a20f-bdde2c398a3d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 18, 18, 'What happens to the kinetic energy of a pendulum bob as it swings from the lowest point to the highest point?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases to zero', NULL, false, NULL, false, NULL, 'At the top the bob is momentarily at rest, so Ek = 0; the energy is now all gravitational potential. Mark scheme (1 mark). B1: C (It decreases to zero).', 1),
('93fb2132-cc07-5df6-aad4-25595adc016c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 19, 19, 'A pendulum bob of mass 0.20 kg rises 4.0 cm above its lowest point at each end of its swing. Calculate its maximum kinetic energy. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '0.07848', 'J', false, NULL, false, NULL, 'Ek max = mgh = 0.20 × 9.81 × 0.040 = 0.0785 J. Mark scheme (2 marks). C1: Ek max = mgh. A1: Ek = 0.0785 J.', 2),
('1438e349-891b-54cb-85b2-3c0f738f9610', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 20, 20, 'An oscillator''s amplitude is halved. What fraction of its energy remains?', NULL, 1, 'multiple_choice'::answer_type, '¼', NULL, false, NULL, false, NULL, 'E = ½mω²x₀², so with ω unchanged E ∝ x₀². Halving x₀ gives (½)² = ¼ of the energy: three quarters has been lost, mostly to damping. Mark scheme (1 mark). B1: A (¼).', 1),
('e26d39c2-8ab4-5d66-aa57-96089818a777', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 21, 21, 'An oscillator has m = 0.30 kg, ω = 8.0 rad s⁻¹, x₀ = 0.050 m. Calculate its potential energy at x = 0.030 m.', NULL, 1, 'numeric'::answer_type, '0.00864', 'J', false, NULL, false, NULL, 'Ep = ½mω²x² = 0.5 × 0.30 × 8.0² × 0.030² = 0.00864 J. Mark scheme (2 marks). C1: Ep = ½mω²x². A1: Ep = 0.00864 J.', 2),
('0bc36249-9ea7-521c-9307-13f05ab66767', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 22, 22, 'Which graph shape shows how the potential energy of a mass–spring oscillator varies with displacement?', NULL, 1, 'multiple_choice'::answer_type, 'A parabola, minimum zero at x = 0', NULL, false, NULL, false, NULL, 'Ep = ½kx²: a U-shaped parabola with its minimum at equilibrium. Mark scheme (1 mark). B1: D (A parabola, minimum zero at x = 0).', 1),
('aacb2e0d-141b-5e8f-880f-ceceafd0c5c8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 23, 23, 'A child on a swing (total mass 30 kg) passes the lowest point at 3.0 m s⁻¹. Calculate the total energy of the oscillation (taking Ep = 0 at the lowest point).', NULL, 1, 'numeric'::answer_type, '135', 'J', false, NULL, false, NULL, 'E = ½mv² = 0.5 × 30 × 3.0² = 135 J. Mark scheme (2 marks). C1: E = ½mv_max². A1: E = 135 J.', 2),
('82ffd59c-46ba-5a36-9dee-aa9ec0c9b863', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 24, 24, 'How often does the kinetic energy of an oscillator of period T reach its maximum?', NULL, 1, 'multiple_choice'::answer_type, 'Twice every period', NULL, false, NULL, false, NULL, 'Ek is maximum each time the object passes through equilibrium: twice per cycle. Mark scheme (1 mark). B1: B (Twice every period).', 1),
('d570529c-aee8-5f2d-a63a-bfb2d467558a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 25, 25, 'An oscillating 0.10 kg mass has kinetic energy 0.020 J at a certain point. Calculate its speed there.', NULL, 1, 'numeric'::answer_type, '0.6325', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2Ek/m) = √(2 × 0.020 ÷ 0.10) = 0.632 m s⁻¹. Mark scheme (2 marks). C1: v = √(2Ek/m). A1: v = 0.632 m s⁻¹.', 2),
('67ff68d7-e1e7-514e-a3c9-ff0845ba6566', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 26, 26, 'A 0.50 kg mass on a spring of constant 200 N m⁻¹ oscillates with amplitude 6.0 cm. Calculate its kinetic energy when the displacement is 4.0 cm.', NULL, 2, 'numeric'::answer_type, '0.2', 'J', false, NULL, false, NULL, 'Ek = ½k(x₀² − x²) = 0.5 × 200 × (0.060² − 0.040²) = 0.20 J. Mark scheme (3 marks). C1: E = ½kx₀². C1: Ek = E − ½kx². A1: Ek = 0.20 J.', 3),
('8fbb2559-2b1f-50b9-a784-0ad2f28e4385', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 27, 27, 'An oscillator has total energy 0.45 J, mass 0.20 kg and period 0.60 s. Calculate its amplitude.', NULL, 2, 'numeric'::answer_type, '0.2026', 'm', false, NULL, false, NULL, 'ω = 2π ÷ 0.60 = 10.5 rad s⁻¹. E = ½mω²x₀², so x₀ = √(2E/mω²) = √(2 × 0.45 ÷ (0.20 × 10.47²)) = 0.203 m. Mark scheme (4 marks). C1: ω = 2π/T. C1: E = ½mω²x₀². C1: rearranged. A1: x₀ = 0.203 m.', 4),
('4e29d2a2-19f4-50a0-9385-c9c5cdf394b8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 28, 28, 'An undamped oscillator has total energy E. What is its kinetic energy when its displacement is half the amplitude?', NULL, 2, 'multiple_choice'::answer_type, '¾E', NULL, false, NULL, false, NULL, 'Ep = ½kx² = ½k(x₀/2)² = ¼E, so Ek = E − ¼E = ¾E. Mark scheme (3 marks). C1: Ep ∝ x². C1: Ek = E − Ep. A1: C (¾E).', 3),
('0cde2831-b745-58c1-9864-b54894c08d65', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 29, 29, 'A mass–spring system has total energy 0.16 J. The spring constant is 80 N m⁻¹. Calculate the amplitude.', NULL, 2, 'numeric'::answer_type, '0.06325', 'm', false, NULL, false, NULL, 'E = ½kx₀², x₀ = √(2E/k) = √(2 × 0.16 ÷ 80) = 0.0632 m. Mark scheme (3 marks). C1: E = ½kx₀². C1: rearranged. A1: x₀ = 0.0632 m.', 3),
('9ad1fc6f-0a28-5e90-971a-fc68df5b9829', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 30, 30, 'A 1.5 kg mass oscillates with s.h.m. of frequency 2.0 Hz and amplitude 4.0 cm. Calculate its maximum kinetic energy.', NULL, 2, 'numeric'::answer_type, '0.1895', 'J', false, NULL, false, NULL, 'ω = 2π × 2.0 = 12.6 rad s⁻¹. Ek max = ½mω²x₀² = 0.5 × 1.5 × (12.6)² × 0.040² = 0.189 J. Mark scheme (3 marks). C1: ω = 2πf. C1: Ek max = ½mω²x₀². C1: x₀ in m.', 3),
('e512c60d-8b83-5809-8411-20f24ae6bf7d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 31, 31, 'Two identical masses on identical springs oscillate. A has amplitude 2 cm, B has amplitude 4 cm. Which is correct?', NULL, 2, 'multiple_choice'::answer_type, 'B has 4 times the energy and twice the maximum speed of A; their periods are equal', NULL, false, NULL, false, NULL, 'E ∝ x₀² (factor 4); v_max = ωx₀ (factor 2); T depends only on m and k. Mark scheme (4 marks). C1: E ∝ x₀². C1: v_max ∝ x₀. C1: T unchanged. A1: A (B has 4 times the energy and twice the maximum speed of A; their periods are equal).', 4),
('c3e2f148-4088-50fd-8edd-056fc570a4ee', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 32, 32, 'A pendulum of length 1.2 m and bob mass 0.40 kg swings with amplitude 8.0 cm. Using E = ½mω²x₀², calculate its energy. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.01046', 'J', false, NULL, false, NULL, 'ω² = g/L = 9.81 ÷ 1.2 = 8.18 s⁻². E = 0.5 × 0.40 × 8.175 × 0.080² = 0.0105 J. Mark scheme (3 marks). C1: ω² = g/L. C1: E = ½mω²x₀². A1: E = 0.0105 J.', 3),
('96c0b680-63e2-5172-8541-f17fc347afb8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 33, 33, 'A 0.20 kg mass oscillates with ω = 12 rad s⁻¹ and amplitude 0.050 m. Find the displacement at which its kinetic energy is three times its potential energy.', NULL, 2, 'numeric'::answer_type, '0.025', 'm', false, NULL, false, NULL, 'Ek = 3Ep means Ep = ¼E: ½mω²x² = ¼ × ½mω²x₀², so x = x₀/2 = 0.050 ÷ 2 = 0.025 m. Mark scheme (4 marks). C1: Ep = E/4. C1: x² = x₀²/4. C1: x. A1: x = 0.025 m.', 4),
('bbcef688-1305-52ee-acf4-6b1993f7f524', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 34, 34, 'For an oscillator, a graph of kinetic energy against displacement is…', NULL, 2, 'multiple_choice'::answer_type, 'an inverted parabola, maximum at x = 0 and zero at x = ±x₀', NULL, false, NULL, false, NULL, 'Ek = ½mω²(x₀² − x²): an upside-down parabola. Mark scheme (3 marks). C1: Ek = ½mω²(x₀² − x²). C1: shape. A1: D (an inverted parabola, maximum at x = 0 and zero at x = ±x₀).', 3),
('b94b5610-5d94-5a4a-ad4e-cea55e03e75c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 35, 35, 'A spring–mass oscillator of total energy 0.090 J has amplitude 3.0 cm. Calculate the restoring force at maximum displacement.', NULL, 2, 'numeric'::answer_type, '6', 'N', false, NULL, false, NULL, 'E = ½kx₀², so k = 2E/x₀² = 2 × 0.090 ÷ 0.030² = 200 N m⁻¹. F = kx₀ = 200 × 0.030 = 6.0 N. Mark scheme (3 marks). C1: k = 2E/x₀². C1: F = kx₀. A1: F = 6.0 N.', 3),
('3d90497f-055a-54e1-8513-1df5dd92c0af', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 36, 36, 'A swing of mass 25 kg (with child) has period 3.5 s and amplitude 1.2 m. Calculate its total energy.', NULL, 2, 'numeric'::answer_type, '58.01', 'J', false, NULL, false, NULL, 'ω = 2π ÷ 3.5 = 1.80 rad s⁻¹. E = ½mω²x₀² = 0.5 × 25 × (1.80)² × 1.2² = 58.0 J. Mark scheme (3 marks). C1: ω = 2π/T. C1: E formula. A1: E = 58.0 J.', 3),
('9c765682-fa88-52d7-be8a-3cd376fd2641', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 37, 37, 'An oscillator of frequency 5.0 Hz is undamped. At what frequency does its potential energy vary?', NULL, 2, 'multiple_choice'::answer_type, '10 Hz', NULL, false, NULL, false, NULL, 'Ep ∝ x² peaks at both extremes in each cycle, so it varies at twice the oscillation frequency. Mark scheme (3 marks). C1: two maxima per cycle. C1: 2f. A1: B (10 Hz).', 3),
('7902d843-2833-5903-8e0e-c97ae7c17ccb', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 38, 38, 'A 0.60 kg mass oscillating with s.h.m. has speed 0.40 m s⁻¹ at x = 0.030 m and speed 0.20 m s⁻¹ at x = 0.050 m. Use energy conservation to find the spring constant.', NULL, 2, 'numeric'::answer_type, '45', 'N m⁻¹', false, NULL, false, NULL, '½mv₁² + ½kx₁² = ½mv₂² + ½kx₂², so k = m(v₁² − v₂²)/(x₂² − x₁²) = 0.60 × (0.40² − 0.20²) ÷ (0.050² − 0.030²) = 45.0 N m⁻¹. Mark scheme (4 marks). C1: energy equation. C1: rearranged for k. C1: substitution. A1: k = 45.0 N m⁻¹.', 4),
('36c1154e-2a0f-5bd8-a453-ccc4cbb2478f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 39, 39, 'A mass on a spring has maximum kinetic energy 0.25 J. Calculate the kinetic energy when it is at 60 % of its amplitude.', NULL, 2, 'numeric'::answer_type, '0.16', 'J', false, NULL, false, NULL, 'Ek = E(1 − x²/x₀²) = 0.25 × (1 − 0.60²) = 0.16 J. Mark scheme (3 marks). C1: Ek = E(1 − x²/x₀²). C1: substitution. A1: Ek = 0.16 J.', 3),
('37474124-452a-52cc-ad13-919cfa7f3015', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 40, 40, 'Why is the total energy of a simple harmonic oscillator proportional to the square of the amplitude?', NULL, 2, 'multiple_choice'::answer_type, 'The maximum potential energy ½kx₀² depends on x₀²', NULL, false, NULL, false, NULL, 'At the extremes all the energy is ½kx₀² (or ½mω²x₀²), so E ∝ x₀². Mark scheme (3 marks). C1: E = ½kx₀². C1: x₀² dependence. A1: C (The maximum potential energy ½kx₀² depends on x₀²).', 3),
('a88f651b-2eb7-5177-82c4-59afb74cec31', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 41, 41, 'A loudspeaker cone of mass 15 g vibrates at 200 Hz with amplitude 0.50 mm. Calculate its vibrational energy.', NULL, 2, 'numeric'::answer_type, '0.002961', 'J', false, NULL, false, NULL, 'E = ½mω²x₀² = 0.5 × 0.015 × (2π × 200)² × (5.0 × 10⁻⁴)² = 0.00296 J. Mark scheme (3 marks). C1: ω = 2πf. C1: E formula. C1: units.', 3),
('96a7b231-9791-5f2f-9bc6-85582f3fa69e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 42, 42, 'An oscillator''s energy falls from 0.80 J to 0.20 J due to damping. The original amplitude was 10 cm. Calculate the new amplitude.', NULL, 2, 'numeric'::answer_type, '0.05', 'm', false, NULL, false, NULL, 'E ∝ x₀²: x₀ = 0.10 × √(0.20 ÷ 0.80) = 0.050 m. Mark scheme (4 marks). C1: E ∝ x₀². C1: ratio. C1: square root. A1: x₀ = 0.050 m.', 4),
('0645b60e-f4b0-573d-bb00-14ecd6f64f47', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 43, 43, 'A 0.40 kg mass on a spring of constant 160 N m⁻¹ is pulled 5.0 cm from equilibrium and released on a frictionless surface. (a) Calculate the total energy. (b) Calculate the maximum speed. (c) Calculate the speed and kinetic energy when the displacement is 3.0 cm. Give only the kinetic energy in (c).', NULL, 3, 'numeric'::answer_type, '0.128', 'J', false, NULL, false, NULL, '(a) E = ½kx₀² = 0.5 × 160 × 0.050² = 0.20 J. (b) v_max = √(2E/m) = √(2 × 0.20 ÷ 0.40) = 1.0 m s⁻¹. (c) Ep = ½ × 160 × 0.030² = 0.072 J, Ek = 0.20 − 0.072 = 0.128 J, v = √(2 × 0.128 ÷ 0.40) = 0.800 m s⁻¹. Mark scheme (6 marks). C1: E = ½kx₀². A1: E. A1: v_max. C1: Ep at 3.0 cm. C1: Ek = E − Ep. A1: Ek = 0.128 J.', 6),
('8536c771-dece-5c7b-980a-bae74664b64d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 44, 44, 'A pendulum bob of mass 0.25 kg on a 1.5 m string swings with amplitude 0.12 m. (a) Calculate ω. (b) Calculate the total energy using E = ½mω²x₀². (c) Calculate the height the bob rises above its lowest point and check against mgh. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.01177', 'J', false, NULL, false, NULL, '(a) ω = √(g/L) = √(9.81 ÷ 1.5) = 2.56 rad s⁻¹. (b) E = 0.5 × 0.25 × 6.540 × 0.12² = 0.0118 J. (c) h ≈ x₀²/2L = 0.12² ÷ (2 × 1.5) = 4.8 × 10⁻³ m, mgh = 0.25 × 9.81 × 4.8 × 10⁻³ = 0.0118 J: the same. Mark scheme (5 marks). C1: ω = √(g/L). A1: ω. A1: E = 0.0118 J. C1: h = x₀²/2L. B1: mgh agrees.', 5),
('52b7f7cd-f946-5c47-9c05-7a9363300b59', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 45, 45, 'A graph shows the potential energy of an oscillating 0.10 kg mass against displacement: a parabola reaching 0.045 J at x = ±0.030 m. (a) Calculate the spring constant. (b) Calculate ω. (c) Calculate the speed of the mass at x = 0.010 m. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.8944', 'm s⁻¹', false, NULL, false, NULL, '(a) ½kx₀² = 0.045, k = 2 × 0.045 ÷ 0.030² = 100 N m⁻¹. (b) ω = √(100 ÷ 0.10) = 31.6 rad s⁻¹. (c) Ep = ½ × 100 × 0.010² = 0.0050 J, Ek = 0.045 − 0.0050 = 0.040 J, v = √(2 × 0.040 ÷ 0.10) = 0.894 m s⁻¹. Mark scheme (6 marks). C1: k from Ep graph. A1: k. A1: ω. C1: Ep at 0.010 m. C1: Ek = E − Ep. A1: v = 0.894 m s⁻¹.', 6),
('880b8ac8-d336-58fa-9867-e9064d4efb9d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 46, 46, 'A vertical spring (k = 40 N m⁻¹) has a 0.10 kg mass that oscillates with amplitude 4.0 cm. (a) Calculate the total oscillation energy. (b) Calculate the maximum speed. (c) Explain why gravitational potential energy does not need separate treatment if displacement is measured from the equilibrium position. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.8', 'm s⁻¹', false, NULL, false, NULL, '(a) E = ½kx₀² = 0.5 × 40 × 0.040² = 0.032 J. (b) v_max = ωx₀ = √(40 ÷ 0.10) × 0.040 = 0.800 m s⁻¹. (c) Measured from equilibrium, the combined effect of gravity and the spring is a restoring force −kx, so the energy behaves as ½kx² alone. Mark scheme (5 marks). A1: E. C1: ω = √(k/m). A1: v_max = 0.800 m s⁻¹. B1: equilibrium shifts. B1: net restoring force −kx.', 5),
('2a641969-7902-58a1-9713-7bfb608a8ace', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 47, 47, 'A 0.30 kg mass oscillates on a spring with total energy 0.12 J and period 0.40 s. (a) Calculate the amplitude. (b) Calculate the displacement at which Ek = Ep. (c) Calculate the time, after passing through equilibrium, at which Ek = Ep first. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.05', 's', false, NULL, false, NULL, '(a) ω = 2π ÷ 0.40 = 15.7 rad s⁻¹, x₀ = √(2E/mω²) = √(2 × 0.12 ÷ (0.30 × 15.71²)) = 0.0569 m. (b) x = x₀/√2 = 0.0403 m. (c) x = x₀ sin ωt = x₀/√2 when ωt = π/4, t = T/8 = 0.40 ÷ 8 = 0.050 s. Mark scheme (6 marks). C1: ω. A1: x₀. C1: x = x₀/√2. A1: x. C1: ωt = π/4. A1: t = 0.050 s.', 6),
('4d0d8495-f273-5a04-9cff-395893b2fead', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 48, 48, 'A trolley of mass 0.80 kg between two springs oscillates with amplitude 8.0 cm and period 1.2 s. Its kinetic energy is recorded by a data logger. (a) Calculate the maximum kinetic energy. (b) State the period of the Ek–time graph. (c) Calculate the kinetic energy 0.15 s after the trolley passes through equilibrium. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.03509', 'J', false, NULL, false, NULL, '(a) v_max = ωx₀ = (2π ÷ 1.2) × 0.080 = 0.419 m s⁻¹, Ek = ½ × 0.80 × 0.4189² = 0.0702 J. (b) 0.60 s. (c) v = v_max cos ωt with ωt = 45°: Ek = Ek,max × cos² 45° = 0.07018 × 0.5 = 0.0351 J. Mark scheme (5 marks). C1: v_max = ωx₀. A1: Ek max. B1: T/2. C1: ωt = π/4. A1: Ek = 0.0351 J.', 5),
('f6d6e641-12a9-5cde-bde3-f34aa7f596a0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 49, 49, 'A 0.15 kg mass on a spring (k = 60 N m⁻¹) oscillates with amplitude 5.0 cm. (a) Calculate the total energy. (b) Calculate the displacement at which the kinetic energy is 0.050 J. (c) Calculate the speed there. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.02887', 'm', false, NULL, false, NULL, '(a) E = ½kx₀² = 0.5 × 60 × 0.050² = 0.075 J. (b) Ep = 0.075 − 0.050 = 0.025 J, x = √(2Ep/k) = √(2 × 0.025 ÷ 60) = 0.0289 m. (c) v = √(2Ek/m) = √(2 × 0.050 ÷ 0.15) = 0.816 m s⁻¹. Mark scheme (5 marks). A1: E. C1: Ep = E − Ek. C1: x = √(2Ep/k). A1: x = 0.0289 m. B1: v.', 5),
('9be6b82c-fa00-517f-95e2-6e8905c99b45', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '326ce4be-3b28-5d8b-baaf-576fbafaa066', 'a-level', '18.8', '9702 coursebook 18.8 · Energy in simple harmonic motion', 50, 50, 'A 0.50 kg pendulum bob on a 2.0 m string is pulled aside so that it is 10 cm higher than its lowest point, and released. (a) Calculate its maximum speed. (b) Calculate the total energy. (c) Air resistance removes 2.0 % of the energy each swing. Calculate the height it reaches after 10 swings. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.08171', 'm', false, NULL, false, NULL, '(a) v = √(2gh) = √(2 × 9.81 × 0.10) = 1.40 m s⁻¹. (b) E = mgh = 0.50 × 9.81 × 0.10 = 0.490 J. (c) Energy (and so height) after 10 swings: h = 0.10 × 0.98¹⁰ = 0.0817 m. Mark scheme (6 marks). C1: v = √(2gh). A1: v. A1: E. M1: × 0.98 per swing. B1: h ∝ E. A1: h = 0.0817 m.', 6)
