('4889cda2-b99c-514c-8ca1-2c8a3bfdcade', '9c765682-fa88-52d7-be8a-3cd376fd2641', '5.0 Hz', 'A', false, 0),
('b7b8cf89-63fb-5687-9ad3-5f6f45299c29', '9c765682-fa88-52d7-be8a-3cd376fd2641', '10 Hz', 'B', true, 1),
