('c954f051-403f-569b-a219-68818d27dd0f', '9c765682-fa88-52d7-be8a-3cd376fd2641', '20 Hz', 'D', false, 3),
('8646a21a-7ae9-53cd-8dfe-c0515bdc1439', '37474124-452a-52cc-ad13-919cfa7f3015', 'The speed is proportional to x₀²', 'A', false, 0),
