('7d3104e4-a141-5d19-8733-cac61316f9db', '37474124-452a-52cc-ad13-919cfa7f3015', 'The maximum potential energy ½kx₀² depends on x₀²', 'C', true, 2),
('ddf6e45c-620e-589b-9b1a-751a659b4ba3', '37474124-452a-52cc-ad13-919cfa7f3015', 'The force is proportional to x₀²', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('81dc8572-f5c1-51fc-904b-4981b4465286', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 7, 7, 'A swinging pendulum gradually comes to rest. Which describes damping?', NULL, 1, 'multiple_choice'::answer_type, 'The loss of energy from an oscillating system, which reduces the amplitude', NULL, false, NULL, false, NULL, 'Damping forces such as friction and air resistance transfer energy out of the system, so the amplitude decreases. Mark scheme (1 mark). B1: C (The loss of energy from an oscillating system, which reduces the amplitude).', 1),
('7f1a32be-b35b-543c-9c98-313610d993a9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 8, 8, 'Which describes light damping?', NULL, 1, 'multiple_choice'::answer_type, 'The system oscillates with an amplitude that decreases gradually', NULL, false, NULL, false, NULL, 'Light damping: many oscillations with a gradually decreasing amplitude (exponential decay). Mark scheme (1 mark). B1: A (The system oscillates with an amplitude that decreases gradually).', 1),
('21062ba8-59cc-5ebf-b6ed-f9185be7e8d7', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 9, 9, 'What is critical damping?', NULL, 1, 'multiple_choice'::answer_type, 'Damping that returns the system to equilibrium in the shortest possible time without oscillating', NULL, false, NULL, false, NULL, 'Critically damped systems do not overshoot and settle fastest. Overdamped ones are slower. Mark scheme (1 mark). B1: D (Damping that returns the system to equilibrium in the shortest possible time without oscillating).', 1),
('a12b3ead-c8e8-5d4d-b37d-63bf251076a5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 10, 10, 'Which is an example of a system designed to be critically damped?', NULL, 1, 'multiple_choice'::answer_type, 'A car''s suspension', NULL, false, NULL, false, NULL, 'A car body should settle quickly after a bump without bouncing. Mark scheme (1 mark). B1: B (A car''s suspension).', 1),
('b40cb0df-2ac6-5c3d-81d3-688647ea4766', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 11, 11, 'What happens to the period of a lightly damped pendulum as its amplitude decreases?', NULL, 1, 'multiple_choice'::answer_type, 'It stays almost the same', NULL, false, NULL, false, NULL, 'Light damping has a negligible effect on the period. Mark scheme (1 mark). B1: C (It stays almost the same).', 1),
('062a1f58-60f4-501a-ae9e-df59bbe9f989', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 12, 12, 'What type of damping is shown by a system that returns to equilibrium very slowly without oscillating?', NULL, 1, 'multiple_choice'::answer_type, 'Overdamping (heavy damping)', NULL, false, NULL, false, NULL, 'Heavy damping prevents oscillation but makes the return slower than critical damping. Mark scheme (1 mark). B1: A (Overdamping (heavy damping)).', 1),
('9e35be0d-60c1-5f25-bd51-9dc6ae6617d5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 13, 13, 'The amplitude of a damped oscillation falls from 12 cm to 9.0 cm. Calculate the fraction of the energy that remains.', NULL, 1, 'numeric'::answer_type, '0.5625', NULL, false, NULL, false, NULL, 'E ∝ A²: fraction = (9.0 ÷ 12)² = 0.5625. Mark scheme (2 marks). C1: E ∝ A². A1: fraction = 0.562.', 2),
('da87c76b-b9d7-5385-b215-fdf3605782e5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 14, 14, 'A damped oscillator loses 10 % of its amplitude every cycle. Starting at 20 cm, calculate its amplitude after 3 cycles.', NULL, 1, 'numeric'::answer_type, '14.58 cm', 'cm', false, NULL, false, NULL, 'A = 20 × 0.90³ = 14.6 cm. Mark scheme (2 marks). C1: × 0.90 each cycle. A1: A = 14.6 cm.', 2),
('a2e74cd1-c06e-5a3e-8c95-7ed02b1dc274', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 15, 15, 'What causes the damping of a swinging pendulum in air?', NULL, 1, 'multiple_choice'::answer_type, 'Air resistance on the bob and friction at the pivot', NULL, false, NULL, false, NULL, 'Air resistance and friction do work against the motion, transferring energy to the surroundings as heat. Mark scheme (1 mark). B1: D (Air resistance on the bob and friction at the pivot).', 1),
('0669e334-bd1c-571b-b17e-169137e59b3d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 16, 16, 'For a lightly damped oscillator, which graph shape describes amplitude against time?', NULL, 1, 'multiple_choice'::answer_type, 'An exponential decay curve', NULL, false, NULL, false, NULL, 'With light damping the amplitude falls by the same fraction each cycle: an exponential decay. Mark scheme (1 mark). B1: B (An exponential decay curve).', 1),
('ae1653dd-e5db-5d38-a8c5-0a786b08ec70', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 17, 17, 'A damped oscillator has energy 0.40 J. Its amplitude is reduced to half. Calculate its energy now.', NULL, 1, 'numeric'::answer_type, '0.1', 'J', false, NULL, false, NULL, 'E ∝ A²: E = 0.40 × 0.5² = 0.10 J. Mark scheme (2 marks). C1: E ∝ A². A1: E = 0.10 J.', 2),
('3daded00-6887-5c56-ae3b-c94c0e85985b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 18, 18, 'Where does the energy lost by a damped oscillator go?', NULL, 1, 'multiple_choice'::answer_type, 'Mostly to internal (thermal) energy of the system and surroundings', NULL, false, NULL, false, NULL, 'Energy is conserved: friction and drag transfer it to thermal energy (and some sound). Mark scheme (1 mark). B1: C (Mostly to internal (thermal) energy of the system and surroundings).', 1),
('b3789673-874d-55fb-8623-84030b4fc9a5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 19, 19, 'A pendulum''s amplitude halves every 5 oscillations. Starting at 16 cm, what is its amplitude after 15 oscillations?', NULL, 1, 'numeric'::answer_type, '2 cm', 'cm', false, NULL, false, NULL, 'After 15 oscillations the amplitude has halved 3 times: 16 ÷ 2³ = 2.0 cm. Mark scheme (2 marks). C1: three halvings. A1: A = 2.0 cm.', 2),
('b3eea4e6-f1ad-532a-a131-3bd945d8332f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 20, 20, 'Shock absorbers in a car contain oil. What is their purpose?', NULL, 1, 'multiple_choice'::answer_type, 'To damp the oscillations of the car body on its springs', NULL, false, NULL, false, NULL, 'The oil''s viscous drag removes energy from the oscillations so the car does not keep bouncing. Mark scheme (1 mark). B1: A (To damp the oscillations of the car body on its springs).', 1),
('e71f37c0-a7aa-5a34-bb5b-3636cf3ccd5f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 21, 21, 'The amplitude of a damped oscillation decreases by 4.0 % each cycle. What percentage of the energy is lost each cycle?', NULL, 1, 'numeric'::answer_type, '7.84', '%', false, NULL, false, NULL, 'Energy fraction remaining = 0.96² = 0.9216, so the percentage lost = (1 − 0.9216) × 100 = 7.8 % each cycle. Mark scheme (2 marks). C1: E ∝ A². A1: loss = 7.8%.', 2),
('912b0b1b-7516-579e-aa63-ec12818dd92e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 22, 22, 'Which graph shows critical damping after a system is displaced and released?', NULL, 1, 'multiple_choice'::answer_type, 'The displacement falls smoothly to zero in the shortest time, with no overshoot', NULL, false, NULL, false, NULL, 'Critical damping: quickest return to equilibrium without crossing it. Mark scheme (1 mark). B1: D (The displacement falls smoothly to zero in the shortest time, with no overshoot).', 1),
('bb650243-0261-5f16-9337-2e4df340e68e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 23, 23, 'A lightly damped oscillator''s amplitude falls by the same fraction each cycle: from 10.0 cm to 8.0 cm in one cycle. Calculate its amplitude after 5 cycles.', NULL, 2, 'numeric'::answer_type, '3.277 cm', 'cm', false, NULL, false, NULL, 'Fraction per cycle = 8.0 ÷ 10.0 = 0.80. After 5 cycles A = 10.0 × 0.80⁵ = 3.28 cm. Mark scheme (3 marks). C1: constant ratio. C1: A = A₀ × 0.80ⁿ. A1: A = 3.28 cm.', 3),
('1dd2e833-1f2e-5275-b6e0-5789c27b2fd9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 24, 24, 'A damped oscillator''s energy falls from 2.0 J to 0.50 J in 8.0 s. Calculate the ratio of final to initial amplitude.', NULL, 2, 'numeric'::answer_type, '0.5', NULL, false, NULL, false, NULL, 'A ∝ √E: ratio = √(0.50 ÷ 2.0) = 0.50. Mark scheme (3 marks). C1: A ∝ √E. C1: substitution. A1: ratio = 0.50.', 3),
('ae06f80d-c57c-5825-a17e-95efcb16cf82', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 25, 25, 'A pendulum swings in air and then in water. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'In water the damping is heavier, so the amplitude decays faster and the period is slightly longer', NULL, false, NULL, false, NULL, 'Water exerts much larger drag forces, so the energy is lost faster; heavy damping also lengthens the period slightly. Mark scheme (3 marks). C1: greater drag. C1: faster decay. A1: B (In water the damping is heavier, so the amplitude decays faster and the period is slightly longer).', 3),
('abc99648-6389-5301-8542-c5622302886c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 26, 26, 'The amplitude of a damped oscillation decays exponentially: A = A₀e^(−t/τ) with τ = 12 s. Starting with A₀ = 5.0 cm, calculate the amplitude after 20 s.', NULL, 2, 'numeric'::answer_type, '0.9444 cm', 'cm', false, NULL, false, NULL, 'A = 5.0 × e^(−20/12) = 5.0 × e^(−1.667) = 0.944 cm. Mark scheme (4 marks). C1: exponential formula. C1: substitution. C1: evaluation. A1: A = 0.944 cm.', 4),
('a9ac9605-7840-5ffc-b235-d43accf63f77', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 27, 27, 'A damped oscillator has amplitude 6.0 cm. 30 s later its amplitude is 3.0 cm. Assuming exponential decay, calculate its amplitude after a further 60 s.', NULL, 2, 'numeric'::answer_type, '0.75 cm', 'cm', false, NULL, false, NULL, 'Halving time = 30 s. A further 60 s is two more halvings: 3.0 ÷ 4 = 0.75 cm. Mark scheme (3 marks). C1: constant halving time. C1: two further halvings. A1: A = 0.75 cm.', 3),
('a1253e79-a0b7-5cf4-8066-0271c3799dbb', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 28, 28, 'A bathroom scale needle is critically damped. Why is this better than light damping?', NULL, 2, 'multiple_choice'::answer_type, 'The needle settles on the reading quickly without oscillating about it', NULL, false, NULL, false, NULL, 'With light damping the needle would oscillate before settling; critical damping gives the fastest reading. Mark scheme (3 marks). C1: no oscillation. C1: quickest settling. A1: C (The needle settles on the reading quickly without oscillating about it).', 3),
('27124414-0ddf-5861-8de4-a4121d0b2b2a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 29, 29, 'A lightly damped pendulum loses 5.0 % of its energy each cycle. Calculate the fraction of the original energy left after 20 cycles, and the fraction of the original amplitude. Give the amplitude fraction.', NULL, 2, 'numeric'::answer_type, '0.5987', NULL, false, NULL, false, NULL, 'Energy fraction = 0.95²⁰ = 0.358. Amplitude fraction = √0.3585 = 0.599. Mark scheme (4 marks). C1: 0.95ⁿ. C1: n = 20. C1: A ∝ √E. A1: fraction = 0.599.', 4),
('9c98ac84-12e4-59cb-adf7-fea34bd6f396', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 30, 30, 'A car with worn shock absorbers goes over a bump. What happens?', NULL, 2, 'multiple_choice'::answer_type, 'It bounces several times before settling, because it is now lightly damped', NULL, false, NULL, false, NULL, 'Worn dampers remove less energy each cycle, so the oscillation persists (light damping). Mark scheme (3 marks). C1: less energy removed. C1: light damping, oscillates. A1: A (It bounces several times before settling, because it is now lightly damped).', 3),
('d69ac07f-cebc-5dde-8503-91f05d95f891', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 31, 31, 'A swing''s amplitude decreases from 1.2 m to 0.90 m in 10 swings. Calculate the percentage of energy lost in those 10 swings.', NULL, 2, 'numeric'::answer_type, '43.75', '%', false, NULL, false, NULL, 'Energy remaining = (0.90 ÷ 1.2)² = 0.5625, so the percentage lost = (1 − 0.5625) × 100 = 43.75 %. Mark scheme (3 marks). C1: E ∝ A². C1: percentage lost. A1: loss = 43.8%.', 3),
('52f8752f-b986-52fd-8f00-7c6790bcb8f5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 32, 32, 'A mass–spring system has total energy 0.20 J. Damping removes 0.020 J each cycle at first. The amplitude starts at 4.0 cm. Calculate the amplitude after the first cycle.', NULL, 2, 'numeric'::answer_type, '3.795 cm', 'cm', false, NULL, false, NULL, 'E after one cycle = 0.20 − 0.020 = 0.18 J. A ∝ √E: A = 4.0 × √(0.18 ÷ 0.20) = 3.79 cm. Mark scheme (4 marks). C1: new energy. C1: A ∝ √E. C1: substitution. A1: A = 3.79 cm.', 4),
('ebe9d1e8-7b60-5f99-b62b-a3dc8d748052', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 33, 33, 'Which change would increase the damping of a mass oscillating on a spring?', NULL, 2, 'multiple_choice'::answer_type, 'Attaching a large card to the mass to increase air resistance', NULL, false, NULL, false, NULL, 'More air resistance means more energy is removed per cycle. Mark scheme (3 marks). C1: larger drag force. C1: more energy lost per cycle. A1: D (Attaching a large card to the mass to increase air resistance).', 3),
('a01f5475-d2c9-5415-b377-a3a820638c0b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 34, 34, 'A damped oscillation has period 0.50 s. Its amplitude falls to 1/e of its starting value in 4.0 s. How many oscillations does it make in this time?', NULL, 2, 'numeric'::answer_type, '8', NULL, false, NULL, false, NULL, 'N = 4.0 ÷ 0.50 = 8.0 oscillations. Mark scheme (3 marks). C1: N = t/T. B1: light damping, period unchanged. A1: N = 8.0.', 3),
('8a6b98a3-4d40-5eb2-8b4a-ecfd75471fad', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 35, 35, 'Two identical pendulums, one with a light bob and one with a heavy bob of the same size, are released together. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The heavy bob''s amplitude decreases more slowly because it has more energy for the same air resistance', NULL, false, NULL, false, NULL, 'The drag force depends on size and speed, not mass, so the same energy is lost per cycle; the heavier bob has more energy, so the fractional loss is smaller. Mark scheme (4 marks). C1: same drag. C1: more stored energy. C1: slower fractional decay. A1: B (The heavy bob''s amplitude decreases more slowly because it has more energy for the same air resistance).', 4),
('39661cfe-003d-56cd-a59f-e243c8051b49', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 36, 36, 'The amplitude of a lightly damped oscillator falls from 8.0 mm to 2.0 mm in 12 s. Calculate the time for the amplitude to fall from 8.0 mm to 4.0 mm.', NULL, 2, 'numeric'::answer_type, '6', 's', false, NULL, false, NULL, 'Exponential decay: 8.0 → 2.0 mm is two halvings in 12 s, so one halving takes 12 ÷ 2 = 6.0 s. Mark scheme (3 marks). C1: two halvings. C1: constant halving time. A1: t = 6.0 s.', 3),
('fcc95418-a095-5fa3-b866-69c536637a6e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 37, 37, 'After a sound pulse, a loudspeaker cone''s displacement falls from 0.40 mm to 0.050 mm in 3.0 ms without oscillating, decaying exponentially as A = A₀e^(−t/τ). Calculate the time constant τ.', NULL, 2, 'numeric'::answer_type, '0.001443', 's', false, NULL, false, NULL, '0.050 ÷ 0.40 = 0.125 = e^(−t/τ), so τ = t/ln 8 = 3.0 × 10⁻³ ÷ ln 8 = 0.00144 s. Mark scheme (4 marks). C1: ratio 1/8. C1: natural logs. C1: τ. A1: τ = 0.00144 s.', 4),
('a99dcdbe-570c-5d1c-aa23-2e4f3049113a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 38, 38, 'A student plots ln(amplitude) against time for a lightly damped oscillator. What shape does she expect?', NULL, 2, 'multiple_choice'::answer_type, 'A straight line with negative gradient', NULL, false, NULL, false, NULL, 'A = A₀e^(−t/τ) gives ln A = ln A₀ − t/τ: linear with gradient −1/τ. Mark scheme (3 marks). C1: ln A = ln A₀ − t/τ. C1: negative gradient. A1: C (A straight line with negative gradient).', 3),
('af00e13c-80f6-5a98-b63d-46956ec4d3fb', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 39, 39, 'A lightly damped oscillator''s amplitude ratio between successive peaks is 0.92. Calculate the fraction of energy lost per cycle.', NULL, 2, 'numeric'::answer_type, '0.1536', NULL, false, NULL, false, NULL, 'Energy ratio = 0.92² = 0.8464, so the fraction lost = 1 − 0.8464 = 0.1536. Mark scheme (3 marks). C1: energy ratio = (amplitude ratio)². C1: 1 − ratio. A1: fraction = 0.154.', 3),
('cefddf50-8340-5e00-bee0-e7b699376325', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 40, 40, 'A swing''s amplitude falls to 70 % of its value every 4 swings. Calculate the amplitude after 12 swings if it started at 1.0 m.', NULL, 2, 'numeric'::answer_type, '0.343', 'm', false, NULL, false, NULL, 'Three lots of 4 swings: A = 1.0 × 0.70³ = 0.343 m. Mark scheme (3 marks). C1: number of 4-swing intervals. C1: 0.70ⁿ. A1: A = 0.343 m.', 3),
('da4bfadc-5fcf-559b-90ac-6f8d9ad132ac', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 41, 41, 'A student records the peak displacements of a damped oscillator at successive cycles: 10.0, 8.5, 7.2, 6.1, 5.2 cm. (a) Show that the decay is exponential. (b) Calculate the fraction of energy lost per cycle. (c) Predict the peak displacement after 10 cycles. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.969 cm', 'cm', false, NULL, false, NULL, '(a) Successive ratios: 8.5 ÷ 10.0 = 0.85, 7.2 ÷ 8.5 = 0.85, 6.1 ÷ 7.2 = 0.85, 5.2 ÷ 6.1 = 0.85: constant, so exponential. (b) Energy lost = 1 − 0.85² = 0.278 per cycle. (c) A = 10.0 × 0.85¹⁰ = 1.97 cm. Mark scheme (6 marks). M1: successive ratios. A1: constant ratio. C1: E ∝ A². A1: fraction lost. C1: A₀rⁿ. A1: A = 1.97 cm.', 6),
('4c37b608-74c0-59da-aa04-bb0c5a774057', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 42, 42, 'A pendulum (period 2.0 s) is released with amplitude 15 cm. After 5.0 minutes its amplitude is 3.0 cm. Assume exponential decay. (a) Calculate the number of oscillations in 5.0 min. (b) Calculate the fraction of amplitude kept per oscillation. (c) Calculate the time for the amplitude to halve. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '129.2', 's', false, NULL, false, NULL, '(a) 300 ÷ 2.0 = 150 oscillations. (b) r¹⁵⁰ = 3.0 ÷ 15 = 0.20, so r = 0.20^(1/150) = 0.98933. (c) A halves when t = 300 × ln 2 ÷ ln 5 = 129 s. Mark scheme (5 marks). A1: 150 oscillations. C1: rⁿ = 0.20. A1: r. M1: logs. A1: t = 129 s.', 5),
('6e0b31cc-12ae-5dfe-92ac-a92cf9fdbd60', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 43, 43, 'A car body (mass 1200 kg) on its suspension (k = 4.8 × 10⁴ N m⁻¹) is pushed down 5.0 cm and released. With the dampers disconnected it oscillates; with them connected it is critically damped. (a) Calculate the natural frequency. (b) Calculate the energy stored at release. (c) Describe and compare the motion in the two cases, and state where the energy goes. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '60', 'J', false, NULL, false, NULL, '(a) f = (1/2π)√(k/m) = (1 ÷ 2π) × √(4.8 × 10⁴ ÷ 1200) = 1.01 Hz. (b) E = ½kx² = 0.5 × 4.8 × 10⁴ × 0.050² = 60 J. (c) Without dampers: many oscillations at about 1 Hz, slowly decaying. Critically damped: returns smoothly to equilibrium in about one quarter-period with no overshoot. The 60 J becomes thermal energy in the damper oil (and tyres). Mark scheme (6 marks). C1: f = (1/2π)√(k/m). A1: f. C1: E = ½kx². A1: E = 60 J. B1: light damping description. B1: critical damping and thermal energy.', 6),
('37c57a22-0c97-5560-99c3-d09f93d751cb', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 44, 44, 'The energy of a lightly damped oscillator falls to half every 15 s. (a) Calculate the time for the amplitude to fall to half. (b) Calculate the percentage of the amplitude left after 1.0 minute. (c) Explain why the amplitude halving time is longer than the energy halving time. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '30', 's', false, NULL, false, NULL, '(a) E ∝ A², so the amplitude halves when the energy has fallen to a quarter: two energy halvings, 2 × 15 = 30 s. (b) 60 s = 2 amplitude halvings: 25 %. (c) Halving A means quartering E, which takes longer than halving E. Mark scheme (5 marks). B1: E ∝ A². M1: amplitude halves when E quarters. A1: 30 s. A1: 25 %. B1: explanation.', 5),
('322a984b-32ce-578a-b64e-b0b1b626e063', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 45, 45, 'A mass on a spring oscillates in air with period 0.80 s; the amplitude falls from 6.0 cm to 5.4 cm in each cycle. The mass is 0.25 kg. (a) Calculate the spring constant. (b) Calculate the energy at amplitude 6.0 cm. (c) Calculate the average power dissipated by damping during the first cycle. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.006593', 'W', false, NULL, false, NULL, '(a) k = 4π²m/T² = 4π² × 0.25 ÷ 0.80² = 15.4 N m⁻¹. (b) E = ½kA² = 0.5 × 15.42 × 0.060² = 0.0278 J. (c) energy lost = ½k(0.060² − 0.054²) = 0.00527 J in 0.80 s, power = 0.005274 ÷ 0.80 = 0.00659 W. Mark scheme (6 marks). C1: k = 4π²m/T². A1: k. A1: E. C1: energy lost in one cycle. C1: P = E/t. A1: P = 0.00659 W.', 6),
('495edb0a-c9b6-523a-b178-e42e567e14f9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 46, 46, 'A lightly damped spring–mass system (m = 0.40 kg, k = 40 N m⁻¹) starts with amplitude 8.0 cm. After 20 oscillations the amplitude is 4.0 cm. (a) Calculate the initial energy. (b) Calculate the energy after 20 oscillations. (c) Calculate the mean power dissipated over the 20 oscillations. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.007639', 'W', false, NULL, false, NULL, '(a) E = ½kA² = 0.5 × 40 × 0.080² = 0.128 J. (b) E = 0.5 × 40 × 0.040² = 0.032 J. (c) T = 2π√(m/k) = 2π × √(0.40 ÷ 40) = 0.628 s, 20T = 12.6 s, P = (0.128 − 0.032) ÷ 12.57 = 0.00764 W. Mark scheme (5 marks). A1: E initial. A1: E final. C1: period. C1: P = ΔE/Δt. A1: P = 0.00764 W.', 5),
('20e179ca-ab5d-5bfc-a746-6923d9686c3b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 47, 47, 'The amplitude A of a damped oscillation is measured: t = 0, 10.0 cm; t = 10 s, 7.4 cm; t = 20 s, 5.5 cm; t = 30 s, 4.1 cm. (a) Show that A decays exponentially. (b) Calculate the time constant τ in A = A₀e^(−t/τ). (c) Predict A at t = 60 s. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.642 cm', 'cm', false, NULL, false, NULL, '(a) Ratios over each 10 s: 7.4 ÷ 10.0 = 0.74, 5.5 ÷ 7.4 = 0.74, 4.1 ÷ 5.5 = 0.75: constant, so exponential. (b) e^(−10/τ) = 0.74, so τ = 10 ÷ ln(1 ÷ 0.74) = 33.2 s. (c) A = 10.0 × e^(−60/33.21) = 1.64 cm. Mark scheme (6 marks). M1: constant ratio in equal times. A1: exponential. C1: ln of ratio. A1: τ. C1: substitution. A1: A = 1.64 cm.', 6),
('266af234-0fa8-533c-b46f-27e2ba0c82e0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 48, 48, 'A car (mass 1000 kg) on its springs (total k = 4.0 × 10⁴ N m⁻¹) is critically damped by its shock absorbers. (a) Calculate the undamped natural period. (b) Explain why a critically damped car is more comfortable than a lightly damped one. (c) Explain why an overdamped car would also be unsatisfactory. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '0.9935', 's', false, NULL, false, NULL, '(a) T = 2π√(m/k) = 2π × √(1000 ÷ 4.0 × 10⁴) = 0.993 s. (b) After a bump it returns to its rest position quickly without bouncing up and down. (c) It would return to equilibrium very slowly, so it might still be compressed when the next bump arrives, giving a harsh ride. Mark scheme (5 marks). C1: T = 2π√(m/k). A1: T = 0.993 s. B1: no oscillation. B1: quick return. B1: overdamped slow return.', 5),
('c69f4bb4-6255-5403-abc5-e0b485c16763', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 49, 49, 'A pendulum clock''s pendulum (energy 0.020 J at full amplitude) loses 0.30 % of its energy each swing to friction. A weight falls slowly to replace this energy. (a) Calculate the energy lost per swing. (b) The period is 2.0 s. Calculate the power the weight must supply. (c) The weight (5.0 kg) falls 1.0 m. Estimate how many days the clock runs per winding. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '18.92', 'days', false, NULL, false, NULL, '(a) ΔE = 0.0030 × 0.020 = 6.0 × 10⁻⁵ J per swing. (b) P = 6.0 × 10⁻⁵ ÷ 2.0 = 3.0 × 10⁻⁵ W. (c) Energy available = mgh = 5.0 × 9.81 × 1.0 = 49 J. Time = 49.05 ÷ 3.0 × 10⁻⁵ = 1.63 × 10⁶ s. In days: 1.635 × 10⁶ ÷ 86400 = 18.9. Mark scheme (6 marks). A1: ΔE per swing. C1: P = ΔE/T. A1: P. C1: mgh. C1: t = E/P. A1: days = 18.9 days.', 6),
('4d064ebf-9daa-5a53-bf50-d8ec3d330317', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'ed31e8cc-8ef4-4b9c-87e0-94fbc7c4ddf0', 'a-level', '18.9', '9702 coursebook 18.9 · Damped oscillations', 50, 50, 'A mass oscillates on a spring in air; then the same system is placed in water. In air the amplitude halves every 40 oscillations; in water it halves every 3 oscillations. (a) Calculate the amplitude fraction kept per oscillation in water. (b) Calculate the fraction of energy lost per oscillation in water. (c) Describe the effect of the water on the period. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.37', NULL, false, NULL, false, NULL, '(a) r³ = 0.5, r = 0.5^(1/3) = 0.794. (b) Energy kept per cycle = r² = 0.630, so lost = 1 − 0.6300 = 0.370. (c) Heavier damping lengthens the period slightly. Mark scheme (5 marks). C1: r³ = 0.5. A1: r. C1: energy ∝ A². A1: fraction = 0.370. B1: period slightly longer.', 5)
