('21009097-2795-5c80-923f-7b3cd6b4e628', '9c98ac84-12e4-59cb-adf7-fea34bd6f396', 'It bounces several times before settling, because it is now lightly damped', 'A', true, 0),
('20bf245d-69e1-5ec5-88a5-51e49ec36020', '9c98ac84-12e4-59cb-adf7-fea34bd6f396', 'It settles faster', 'B', false, 1),
('520ea5dc-8d22-5c09-aa59-15e1cec4ab12', '9c98ac84-12e4-59cb-adf7-fea34bd6f396', 'It does not move at all', 'C', false, 2),
('9e06932c-7184-5310-9a81-7e92d96560b7', '9c98ac84-12e4-59cb-adf7-fea34bd6f396', 'It is critically damped', 'D', false, 3),
('4fec1b57-32ef-52df-8d87-288ec54cf695', 'ebe9d1e8-7b60-5f99-b62b-a3dc8d748052', 'Using a stiffer spring', 'A', false, 0),
('94625041-df9c-59b2-bded-5a7893c07ab3', 'ebe9d1e8-7b60-5f99-b62b-a3dc8d748052', 'Increasing the amplitude', 'B', false, 1),
('c4cb9fc9-8378-5e08-aadf-346965af72f1', 'ebe9d1e8-7b60-5f99-b62b-a3dc8d748052', 'Removing air from around it', 'C', false, 2),
('6f3c6342-dddc-5260-8f94-525823eb7dac', 'ebe9d1e8-7b60-5f99-b62b-a3dc8d748052', 'Attaching a large card to the mass to increase air resistance', 'D', true, 3),
('32d18c02-f147-5cb3-83e5-2615179f0593', '8a6b98a3-4d40-5eb2-8b4a-ecfd75471fad', 'The light bob''s amplitude decreases more slowly', 'A', false, 0),
('9ac532d4-eb92-5fb8-a15d-8da06d4223c5', '8a6b98a3-4d40-5eb2-8b4a-ecfd75471fad', 'The heavy bob''s amplitude decreases more slowly because it has more energy for the same air resistance', 'B', true, 1),
('a9b53907-4d52-5cf2-bd2d-190f87cf3676', '8a6b98a3-4d40-5eb2-8b4a-ecfd75471fad', 'Both decay at the same rate', 'C', false, 2),
('4b7db855-07ba-54c2-8df9-925ad070a6a0', '8a6b98a3-4d40-5eb2-8b4a-ecfd75471fad', 'The heavy bob has a longer period', 'D', false, 3),
('90802fe8-cf97-5766-9519-ad002c653f9c', 'a99dcdbe-570c-5d1c-aa23-2e4f3049113a', 'A straight line with positive gradient', 'A', false, 0),
('3e71c0ff-4c13-5f03-bbbe-fec5b2b62290', 'a99dcdbe-570c-5d1c-aa23-2e4f3049113a', 'A parabola', 'B', false, 1),
('bc02c9bd-87dd-5cf2-950b-209074ebd44f', 'a99dcdbe-570c-5d1c-aa23-2e4f3049113a', 'A straight line with negative gradient', 'C', true, 2),
('4314706f-92ad-57fe-aa84-62e25ff0caeb', 'a99dcdbe-570c-5d1c-aa23-2e4f3049113a', 'An exponential curve', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('6a2cd0f5-5765-51c0-820c-6736299270d4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 9, 9, 'A system with natural frequency f₀ is driven at a range of frequencies. What is resonance?', NULL, 1, 'multiple_choice'::answer_type, 'A large increase in amplitude when the driving frequency equals the natural frequency', NULL, false, NULL, false, NULL, 'At resonance the driver transfers energy most efficiently, giving maximum amplitude. Mark scheme (1 mark). B1: C (A large increase in amplitude when the driving frequency equals the natural frequency).', 1),
('9d67a03d-4200-50df-a534-33ec90a145cc', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 10, 10, 'Which is an example of useful resonance?', NULL, 1, 'multiple_choice'::answer_type, 'A microwave oven heating water molecules', NULL, false, NULL, false, NULL, 'Microwaves at about 2.45 GHz make water molecules absorb energy strongly. Mark scheme (1 mark). B1: A (A microwave oven heating water molecules).', 1),
('1f6f3951-e89e-578f-a957-6fcd4ab0b866', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 11, 11, 'What is the effect of increasing damping on the resonance peak of a driven oscillator?', NULL, 1, 'multiple_choice'::answer_type, 'The peak becomes lower and broader', NULL, false, NULL, false, NULL, 'More damping removes energy faster, reducing the maximum amplitude and spreading the response over more frequencies. Mark scheme (1 mark). B1: D (The peak becomes lower and broader).', 1),
('9a70e231-0d6a-59db-82ae-12e94b8cfa66', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 12, 12, 'A singer shatters a wine glass with a note. Which explains this?', NULL, 1, 'multiple_choice'::answer_type, 'The note''s frequency matches the glass''s natural frequency, so the glass resonates with a large amplitude', NULL, false, NULL, false, NULL, 'Resonance builds up a large vibration amplitude until the glass breaks. Mark scheme (1 mark). B1: B (The note''s frequency matches the glass''s natural frequency, so the glass resonates with a large amplitude).', 1),
('680bdcbe-7dd5-5147-8e4c-1381b1b9d47b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 13, 13, 'A mass–spring system with m = 0.20 kg and k = 80 N m⁻¹ is driven by a variable-frequency vibrator. At what frequency does resonance occur?', NULL, 1, 'numeric'::answer_type, '3.183', 'Hz', false, NULL, false, NULL, 'f₀ = (1/2π)√(k/m) = (1 ÷ 2π) × √(80 ÷ 0.20) = 3.18 Hz. Mark scheme (2 marks). C1: f₀ = (1/2π)√(k/m). A1: f₀ = 3.18 Hz.', 2),
('6e70bea1-ee1e-56d2-a7de-0da56282f9b6', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 14, 14, 'A simple pendulum of length 0.62 m is driven by a series of small pushes. At what driving frequency is the response greatest? Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '0.6331', 'Hz', false, NULL, false, NULL, 'f₀ = (1/2π)√(g/L) = (1 ÷ 2π) × √(9.81 ÷ 0.62) = 0.633 Hz. Mark scheme (2 marks). C1: f₀ = (1/2π)√(g/L). A1: f₀ = 0.633 Hz.', 2),
('1efa3501-4594-518d-a00d-0657c11deb7d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 15, 15, 'In Barton''s pendulums, several pendulums hang from a string with a heavy driver pendulum. Which pendulum swings with the largest amplitude?', NULL, 1, 'multiple_choice'::answer_type, 'The one with the same length as the driver', NULL, false, NULL, false, NULL, 'The pendulum with the same length has the same natural frequency as the driver, so it resonates. Mark scheme (1 mark). B1: C (The one with the same length as the driver).', 1),
('d99bffe3-6bea-5252-a09f-187f159f0990', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 16, 16, 'Why are soldiers told to break step when crossing a small bridge?', NULL, 1, 'multiple_choice'::answer_type, 'Marching in step could drive the bridge at its natural frequency and cause resonance', NULL, false, NULL, false, NULL, 'Regular footsteps act as a periodic driving force; if its frequency matched the bridge''s, large oscillations could build up. Mark scheme (1 mark). B1: A (Marching in step could drive the bridge at its natural frequency and cause resonance).', 1),
('594df0c7-c028-55ed-b358-50426823ba2f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 17, 17, 'In MRI scanning, radio waves are absorbed by hydrogen nuclei. This is an example of…', NULL, 1, 'multiple_choice'::answer_type, 'resonance', NULL, false, NULL, false, NULL, 'The radio frequency matches the precession frequency of the protons in the magnetic field, so they absorb energy strongly. Mark scheme (1 mark). B1: D (resonance).', 1),
('7222acfc-b669-50dd-8f9f-e727ce29ebf3', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 18, 18, 'A driven oscillator has very little damping. How does its amplitude behave as the driving frequency passes through the natural frequency?', NULL, 1, 'multiple_choice'::answer_type, 'It rises to a very large, sharp peak at the natural frequency', NULL, false, NULL, false, NULL, 'With little damping, resonance gives a tall narrow peak. Mark scheme (1 mark). B1: B (It rises to a very large, sharp peak at the natural frequency).', 1),
('f54d2a9c-47ca-5d2d-a111-a1433784da44', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 19, 19, 'A child''s swing has natural period 2.4 s. How often (in pushes per minute) should it be pushed for maximum amplitude?', NULL, 1, 'numeric'::answer_type, '25', NULL, false, NULL, false, NULL, 'f₀ = 1/2.4 Hz, so pushes per minute = 60 ÷ 2.4 = 25. Mark scheme (2 marks). C1: once per period. A1: pushes = 25.0.', 2),
('2ef8914e-68fb-5f24-a0d5-709ef5cf06d6', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 20, 20, 'Which type of oscillation occurs when a system vibrates at the frequency of a periodic external force?', NULL, 1, 'multiple_choice'::answer_type, 'Forced oscillation', NULL, false, NULL, false, NULL, 'A forced oscillation follows the driver''s frequency. Mark scheme (1 mark). B1: C (Forced oscillation).', 1),
('06647ffd-870b-5500-a65f-cf54a1aa390c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 21, 21, 'Why must the natural frequency of a building''s structure be kept away from the frequencies of likely earthquakes?', NULL, 1, 'multiple_choice'::answer_type, 'To avoid resonance, which would give dangerously large oscillations', NULL, false, NULL, false, NULL, 'If the ground shakes at the building''s natural frequency, the amplitude grows and the structure can fail. Mark scheme (1 mark). B1: A (To avoid resonance, which would give dangerously large oscillations).', 1),
('1172c17d-9440-5663-ba8e-becfef4eb755', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 22, 22, 'A washing machine on its springs has a natural frequency of 4.5 Hz. At what drum speed, in rev min⁻¹, will it resonate?', NULL, 1, 'numeric'::answer_type, '270', 'rev min⁻¹', false, NULL, false, NULL, 'Resonance when the drum turns at 4.5 rev s⁻¹ = 4.5 × 60 = 270 rev min⁻¹. Mark scheme (2 marks). C1: × 60. A1: speed = 270 rev min⁻¹.', 2),
('036c1c6e-3fed-55e3-969e-69e518d511d9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 23, 23, 'Which statement about forced oscillations is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The amplitude depends on how close the driving frequency is to the natural frequency', NULL, false, NULL, false, NULL, 'The response peaks at resonance and is smaller further from it. Mark scheme (1 mark). B1: D (The amplitude depends on how close the driving frequency is to the natural frequency).', 1),
('826a8d76-8029-5f7f-b44d-2ffa0b3b8d3e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 24, 24, 'A radio is tuned to a station. Which statement best describes what happens in the tuning circuit?', NULL, 1, 'multiple_choice'::answer_type, 'The circuit''s natural frequency is adjusted to match the station''s frequency, so it resonates with that signal', NULL, false, NULL, false, NULL, 'Tuning changes the circuit''s natural frequency; at resonance it responds strongly to the chosen station only. Mark scheme (2 marks). C1: resonance at chosen frequency. A1: B (The circuit''s natural frequency is adjusted to match the station''s frequency, so it resonates with that signal).', 2),
('f109bf18-70ce-5baa-8501-55d7759e480b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 25, 25, 'A driven oscillator is heavily damped. Which change to its resonance curve is NOT caused by the damping?', NULL, 2, 'multiple_choice'::answer_type, 'The natural frequency becomes much higher', NULL, false, NULL, false, NULL, 'Damping lowers and broadens the peak and shifts it slightly lower; it does not raise the natural frequency. Mark scheme (3 marks). C1: lower, broader peak. C1: slight shift to lower frequency. A1: C (The natural frequency becomes much higher).', 3),
('761447dc-2c1e-589b-8992-4fd07450a661', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 26, 26, 'A wobbly table has a natural frequency of 6.0 Hz. A washing machine on it spins at 0, then speeds up to 1200 rev min⁻¹. Calculate the drum speed, in rev min⁻¹, at which the table rattles most.', NULL, 2, 'numeric'::answer_type, '360', 'rev min⁻¹', false, NULL, false, NULL, 'The drum must turn at 6.0 rev s⁻¹, which is 6.0 × 60 = 360 rev min⁻¹: the table resonates as the drum passes this speed. Mark scheme (3 marks). C1: resonance when f_drive = f₀. C1: Hz to rev min⁻¹. A1: speed = 360 rev min⁻¹.', 3),
('38366736-206e-5755-9020-c8f34c42baaa', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 27, 27, 'At resonance, what is the phase relationship between the driving force and the displacement of a lightly damped oscillator?', NULL, 2, 'multiple_choice'::answer_type, 'The displacement lags the driving force by π/2', NULL, false, NULL, false, NULL, 'At resonance the force is in phase with the velocity, so the displacement lags the force by a quarter cycle — this gives maximum power transfer. Mark scheme (4 marks). C1: force in phase with velocity. C1: displacement lags by π/2. C1: maximum power transfer. A1: A (The displacement lags the driving force by π/2).', 4),
('cfc9444a-1a69-5119-b34c-71e533cdb39a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 28, 28, 'A 0.50 kg mass on a spring resonates when driven at 2.8 Hz. Calculate the spring constant.', NULL, 2, 'numeric'::answer_type, '154.8', 'N m⁻¹', false, NULL, false, NULL, 'k = 4π²mf₀² = 4π² × 0.50 × 2.8² = 155 N m⁻¹. Mark scheme (3 marks). C1: f₀ = (1/2π)√(k/m). C1: rearranged. A1: k = 155 N m⁻¹.', 3),
('d87d85c0-1c83-577f-b331-d648688e8ec6', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 29, 29, 'A car''s steering wheel vibrates strongly at 25 m s⁻¹ because an unbalanced wheel (radius 0.32 m) drives the steering at its natural frequency. Calculate that natural frequency.', NULL, 2, 'numeric'::answer_type, '12.43', 'Hz', false, NULL, false, NULL, 'The wheel turns once per circumference: f = v/(2πr) = 25 ÷ (2π × 0.32) = 12.4 Hz. Mark scheme (4 marks). B1: driving frequency = wheel rotation rate. C1: f = v/2πr. C1: substitution. A1: f₀ = 12.4 Hz.', 4),
('f3fd2472-b3d0-5352-a279-89f9e24e7ea5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 30, 30, 'A lightly damped and a heavily damped oscillator with the same natural frequency are driven at the same frequencies. Far below resonance, how do their amplitudes compare?', NULL, 2, 'multiple_choice'::answer_type, 'They are almost the same', NULL, false, NULL, false, NULL, 'Far from resonance the amplitude is set mainly by the stiffness (or mass), not the damping. The difference is large only near resonance. Mark scheme (3 marks). C1: damping matters mainly near resonance. C1: similar amplitudes. A1: D (They are almost the same).', 3),
('4db17b7e-9235-5e29-9c14-ac948ed77aa0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 31, 31, 'A pendulum of length 0.40 m is suspended from a beam that vibrates horizontally. Calculate the period of the beam vibration that would cause resonance. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '1.269', 's', false, NULL, false, NULL, 'Resonance when T_drive = T₀ = 2π√(L/g) = 2π × √(0.40 ÷ 9.81) = 1.27 s. Mark scheme (3 marks). C1: T₀ = 2π√(L/g). C1: drive period = T₀. A1: T = 1.27 s.', 3),
('45cc75fe-19ac-53b1-a70c-af8f4d27c8c0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 32, 32, 'Engineers find that a footbridge sways at 1.0 Hz when crowds walk on it. Which fix would most directly stop the resonance?', NULL, 2, 'multiple_choice'::answer_type, 'Fit dampers that absorb energy from the sway', NULL, false, NULL, false, NULL, 'Dampers reduce the amplitude at resonance by removing energy each cycle (the Millennium Bridge was fixed this way). Mark scheme (3 marks). C1: damping reduces resonance amplitude. C1: identifies dampers. A1: B (Fit dampers that absorb energy from the sway).', 3),
('06a7c8a5-ba0f-5691-97e8-6863c9cfb960', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 33, 33, 'A 2.0 kg mass on a spring of constant 200 N m⁻¹ is driven at a variable frequency. The driver is set to 1.0 Hz and then slowly increased. Calculate the frequency at which the amplitude peaks, and the factor by which this exceeds the starting frequency. Give the peak frequency.', NULL, 2, 'numeric'::answer_type, '1.592', 'Hz', false, NULL, false, NULL, 'f₀ = (1 ÷ 2π) × √(200 ÷ 2.0) = 1.59 Hz, which is 1.59 ÷ 1.0 = 1.59 times the start. Mark scheme (4 marks). C1: f₀ formula. C1: substitution. B1: ratio. A1: f₀ = 1.59 Hz.', 4),
('a326222e-f047-5179-a53a-24a81486b062', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 34, 34, 'Why does a lightly damped forced oscillator take a long time to settle to a steady amplitude after the driver is switched on?', NULL, 2, 'multiple_choice'::answer_type, 'Energy builds up gradually over many cycles until the energy lost per cycle equals the energy supplied', NULL, false, NULL, false, NULL, 'Steady state is reached when input power equals loss; with little damping the loss is small, so amplitude (and energy) builds up over many cycles. Mark scheme (3 marks). C1: energy builds up. C1: input = loss at steady state. A1: C (Energy builds up gradually over many cycles until the energy lost per cycle equals the energy supplied).', 3),
('a1ffc43d-f5fe-505f-bef6-bb91971fabe8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 35, 35, 'A wine glass has a natural frequency of 880 Hz. A loudspeaker plays a note one octave lower. By what factor is the driving frequency below the natural frequency?', NULL, 2, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'An octave lower is half the frequency: 440 Hz, which is 880 ÷ 440 = 2.0 times lower, so the glass does not resonate. Mark scheme (3 marks). C1: octave = factor 2. C1: ratio. A1: factor = 2.0.', 3),
('50162fb2-bed5-54e0-b8c2-84b4204c259e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 36, 36, 'A student drives a mass–spring system and plots amplitude against frequency for two damping settings. Curve X has a peak of 8 cm at 2.0 Hz; curve Y has a peak of 3 cm at 1.95 Hz. Which conclusion is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Y is more heavily damped than X', NULL, false, NULL, false, NULL, 'Heavier damping gives a lower peak at a slightly lower frequency: Y. Mark scheme (4 marks). C1: lower peak. C1: slightly lower frequency. C1: more damping. A1: A (Y is more heavily damped than X).', 4),
('ad922a09-6b67-5447-af86-928136bcce0c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 37, 37, 'In a car, a loose panel rattles when the engine runs at 2400 rev min⁻¹. The engine produces two vibration pulses per revolution. Calculate the natural frequency of the panel.', NULL, 2, 'numeric'::answer_type, '80', 'Hz', false, NULL, false, NULL, 'Revolutions per second = 2400 ÷ 60 = 40. Driving frequency = 2 × 40 = 80 Hz = natural frequency of the panel. Mark scheme (3 marks). C1: rev s⁻¹. C1: × 2 pulses. A1: f₀ = 80 Hz.', 3),
('102527ef-a65d-54f0-88aa-2b7bd231940e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 38, 38, 'Why are car engines mounted on rubber blocks?', NULL, 2, 'multiple_choice'::answer_type, 'The rubber damps vibrations so they are not passed strongly to the car body, and reduces the size of any resonance', NULL, false, NULL, false, NULL, 'Rubber absorbs energy (damping) and isolates the body from engine vibrations. Mark scheme (3 marks). C1: damping. C1: reduces transmitted vibration. A1: D (The rubber damps vibrations so they are not passed strongly to the car body, and reduces the size of any resonance).', 3),
('351eb1f2-2d6c-5b49-b19d-14ea40ffabdb', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 39, 39, 'A pendulum clock is placed on a shelf that vibrates at 0.70 Hz. Calculate the pendulum length that would resonate with the shelf, and say whether the usual 0.99 m pendulum would. Give the length. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.5071', 'm', false, NULL, false, NULL, 'L = g/(2πf)² = 9.81 ÷ (2π × 0.70)² = 0.507 m. A 0.99 m pendulum has f₀ = 0.50 Hz, so it would not resonate. Mark scheme (4 marks). C1: f₀ = (1/2π)√(g/L). C1: rearranged for L. B1: comparison. A1: L = 0.507 m.', 4),
('f09d4d35-bbbe-5c21-8810-04cee26c9f46', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 40, 40, 'A tall chimney is fitted with spiral strakes on its outside. Why?', NULL, 2, 'multiple_choice'::answer_type, 'They break up the regular vortices shed by the wind, which could otherwise drive the chimney at its natural frequency', NULL, false, NULL, false, NULL, 'Wind shedding regular vortices produces a periodic force; disrupting it prevents resonance. Mark scheme (3 marks). C1: periodic driving from vortices. C1: prevents resonance. A1: B (They break up the regular vortices shed by the wind, which could otherwise drive the chimney at its natural frequency).', 3),
('08d3b87d-39b8-5833-ac84-64a838af8d96', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 41, 41, 'Which statement about the frequency at which a lightly damped oscillator responds most strongly is correct?', NULL, 2, 'multiple_choice'::answer_type, 'It is very close to (just below) the natural frequency', NULL, false, NULL, false, NULL, 'With light damping, the amplitude peaks at a driving frequency just below f₀. Mark scheme (3 marks). C1: peak near f₀. C1: slightly below for damped system. A1: C (It is very close to (just below) the natural frequency).', 3),
('d06551a0-52f6-5ce9-95a1-92cbe874f5d0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 42, 42, 'A loudspeaker drives an air-filled tube whose air column resonates at 280 Hz. Calculate the driving period at resonance in milliseconds.', NULL, 2, 'numeric'::answer_type, '3.571 ms', 'ms', false, NULL, false, NULL, 'T = 1/f = 1 ÷ 280 = 0.00357 s. In ms: 0.003571 × 1000 = 3.57 ms. Mark scheme (3 marks). C1: resonance at f₀. C1: T = 1/f. A1: T = 3.57 ms.', 3),
('e7386059-3c46-558e-a605-176ed47883be', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 43, 43, 'A mass–spring system (m = 0.40 kg, k = 64 N m⁻¹) is driven by a vibrator. Readings of amplitude A against frequency f: 1.0 Hz 0.8 cm; 1.5 Hz 2.0 cm; 2.0 Hz 7.5 cm; 2.5 Hz 2.2 cm; 3.0 Hz 0.9 cm. (a) Calculate the natural frequency. (b) State which reading is closest to resonance and comment. (c) Predict how the curve changes if a card is attached to the mass. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '2.013', 'Hz', false, NULL, false, NULL, '(a) f₀ = (1/2π)√(k/m) = (1 ÷ 2π) × √(64 ÷ 0.40) = 2.01 Hz. (b) 2.0 Hz gives the largest amplitude (7.5 cm), as expected since f₀ ≈ 2.0 Hz. (c) More air resistance: the peak is lower and broader, and shifts slightly to a lower frequency. Mark scheme (6 marks). C1: f₀ formula. C1: substitution. A1: f₀ = 2.01 Hz. B1: peak at 2.0 Hz. B1: lower peak. B1: broader, slightly lower frequency.', 6),
('5497c7c1-b7f1-5e61-af09-490fc255ca58', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 44, 44, 'A washing machine (drum assembly 50 kg) on springs of total stiffness 3.2 × 10⁴ N m⁻¹ spins up to 1400 rev min⁻¹. (a) Calculate its natural frequency. (b) Calculate the spin speed, in rev min⁻¹, at which it resonates. (c) Explain why it shakes briefly while spinning up but runs smoothly at full speed. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '241.6', 'rev min⁻¹', false, NULL, false, NULL, '(a) f₀ = (1 ÷ 2π) × √(3.2 × 10⁴ ÷ 50) = 4.03 Hz. (b) 4.026 × 60 = 242 rev min⁻¹. (c) The drum passes through the resonant speed on the way up, so the shaking is brief. At 1400 rev min⁻¹ the driving frequency is far above f₀ and the response is small. Mark scheme (5 marks). C1: f₀ formula. A1: f₀. A1: speed = 242 rev min⁻¹. B1: passes through resonance. B1: far from f₀ at full speed.', 5),
('d5587662-9b4b-5d4c-b0b7-1afaa5b29313', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 45, 45, 'An engineer models a footbridge as a mass of 1.2 × 10⁵ kg on a spring, with sideways natural frequency 0.90 Hz. (a) Calculate the effective sideways stiffness. (b) Pedestrians walking at 1.8 steps per second push sideways at half the step rate. Explain why the bridge resonates. (c) Dampers are fitted that remove 30 % of the oscillation energy each cycle. Calculate the fraction of amplitude remaining after 5 cycles once the crowd leaves. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.41', NULL, false, NULL, false, NULL, '(a) k = 4π²mf₀² = 4π² × 1.2 × 10⁵ × 0.90² = 3.84 × 10⁶ N m⁻¹. (b) Sideways driving frequency = 1.8 ÷ 2 = 0.90 Hz = f₀. (c) Energy left = 0.70⁵ = 0.168, amplitude fraction = √0.1681 = 0.410. Mark scheme (6 marks). C1: k = 4π²mf². A1: k. B1: 0.90 Hz = f₀. C1: 0.70ⁿ. C1: A ∝ √E. A1: fraction = 0.410.', 6),
('0ec13525-f1ca-54db-a3a8-822d6fa662dd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 46, 46, 'A pendulum of length 1.50 m hangs from a horizontal rod. The rod is moved back and forth with a small amplitude, starting slowly and gradually increasing the frequency. (a) Calculate the frequency at which the pendulum swings most. (b) Describe the phase of the pendulum relative to the rod well below and well above this frequency. Give only the answer to (a). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.407', 'Hz', false, NULL, false, NULL, '(a) f₀ = (1/2π)√(g/L) = (1 ÷ 2π) × √(9.81 ÷ 1.50) = 0.407 Hz. (b) Well below f₀ the bob moves in phase with the rod (it simply follows it). At f₀ it lags by π/2 with a large amplitude. Well above f₀ it moves in antiphase with a small amplitude. Mark scheme (5 marks). C1: f₀ formula. A1: f₀ = 0.407 Hz. B1: in phase below. B1: π/2 at resonance. B1: antiphase above.', 5),
('0e10b878-a27c-5a5b-b9af-26e5ace0ce2b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 47, 47, 'A 0.25 kg mass on a spring (k = 25 N m⁻¹) is driven at resonance. Damping removes energy at a rate P = bv², with b = 0.20 kg s⁻¹, and the steady amplitude is 4.0 cm. (a) Calculate the natural angular frequency. (b) Calculate the maximum speed. (c) Calculate the average power the driver supplies (the average of v² is half its maximum). Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.016', 'W', false, NULL, false, NULL, '(a) ω₀ = √(k/m) = √(25 ÷ 0.25) = 10 rad s⁻¹. (b) v_max = ω₀A = 10 × 0.040 = 0.40 m s⁻¹. (c) average power = b × ½v_max² = 0.20 × 0.5 × 0.40² = 0.0160 W (at steady state the driver supplies exactly what damping removes). Mark scheme (6 marks). C1: ω₀ = √(k/m). A1: ω₀. A1: v_max. C1: P = b × mean v². B1: input = loss at steady state. A1: P = 0.0160 W.', 6),
('0c06d632-e692-5e5a-8cab-b2ea915e4194', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 48, 48, 'An earthquake shakes the ground at 1.5 Hz. Three buildings have natural frequencies: P 0.4 Hz, Q 1.5 Hz, R 4.0 Hz. (a) State which building is most at risk and why. (b) Building Q is modelled as a 2.0 × 10⁶ kg mass on a spring. Calculate its effective stiffness. (c) Suggest two ways to protect Q. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.777e8', 'N m⁻¹', false, NULL, false, NULL, '(a) Q: its natural frequency equals the driving frequency, so it resonates with a large amplitude. (b) k = 4π²mf² = 4π² × 2.0 × 10⁶ × 1.5² = 1.78 × 10⁸ N m⁻¹. (c) Add damping (dampers or a tuned mass damper) and/or change the stiffness or mass so f₀ moves away from 1.5 Hz (or use base isolation). Mark scheme (5 marks). B1: Q. B1: resonance reason. C1: k = 4π²mf². A1: k = 1.78 × 10⁸ N m⁻¹. B1: two valid methods.', 5),
('b2a1412c-7686-5ca5-99ea-ae7fa6bac55e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 49, 49, 'A 0.20 kg mass on a spring (k = 20 N m⁻¹) is driven by a motor whose frequency rises from 0.20 Hz to 3.0 Hz. (a) Calculate the natural frequency. (b) Explain, in terms of energy transfer, why the amplitude is greatest near this frequency. (c) The mass is replaced by one of 0.80 kg. State the new resonant frequency. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.7958', 'Hz', false, NULL, false, NULL, '(a) f₀ = (1 ÷ 2π) × √(20 ÷ 0.20) = 1.59 Hz. (b) At f₀ the driving force is in phase with the velocity, so it does positive work on the mass throughout each cycle: maximum energy transfer. (c) Four times the mass halves f₀: f₀ = 1.592 ÷ 2 = 0.796 Hz. Mark scheme (5 marks). A1: f₀. B1: force in phase with velocity. B1: maximum energy transfer. C1: f ∝ 1/√m. A1: f₀ = 0.796 Hz.', 5),
('1c18fedb-0b3d-5384-80e4-afc1f60a179c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'a-level', '18.10', '9702 coursebook 18.10 · Damped and forced oscillations, resonance', 50, 50, 'A tall building has natural frequency 0.25 Hz and effective mass 4.0 × 10⁷ kg. During a storm, wind gusts arrive every 4.0 s. (a) Explain why the building may sway dangerously. (b) Calculate the effective stiffness. (c) Engineers stiffen the structure so that k increases by 44 %. Calculate the new natural frequency. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.3', 'Hz', false, NULL, false, NULL, '(a) Gusts every 4.0 s means f = 0.25 Hz, equal to f₀: resonance. (b) k = 4π²mf² = 4π² × 4.0 × 10⁷ × 0.25² = 9.87 × 10⁷ N m⁻¹. (c) f ∝ √k: f = 0.25 × √1.44 = 0.300 Hz, now away from the gust frequency. Mark scheme (6 marks). B1: 0.25 Hz drive equals f₀. C1: k = 4π²mf². A1: k. C1: f ∝ √k. A1: f = 0.300 Hz. B1: avoids resonance.', 6)
