('4c6c160b-e799-5559-b570-301ce9488509', '1f6f3951-e89e-578f-a957-6fcd4ab0b866', 'There is no effect', 'C', false, 2),
('8a73d0ae-93a4-5d8e-986a-18caccf827a5', '1f6f3951-e89e-578f-a957-6fcd4ab0b866', 'The peak becomes lower and broader', 'D', true, 3),
('8c10fd03-f88a-5b1e-862e-8c23c71416e3', '9a70e231-0d6a-59db-82ae-12e94b8cfa66', 'The sound is very loud at all frequencies', 'A', false, 0),
('4992fe41-11bb-51ee-a5d0-b9e6e2bcc736', '9a70e231-0d6a-59db-82ae-12e94b8cfa66', 'The note''s frequency matches the glass''s natural frequency, so the glass resonates with a large amplitude', 'B', true, 1),
('9c0a71ec-07d9-5dae-b4c8-8377cb2804b3', '9a70e231-0d6a-59db-82ae-12e94b8cfa66', 'The glass is heated by the sound', 'C', false, 2),
('21af3bab-32d9-5763-b477-53a5e8b4170d', '9a70e231-0d6a-59db-82ae-12e94b8cfa66', 'The singer''s breath pushes the glass', 'D', false, 3),
('56c7c5ab-7d9d-5cb8-965f-38a104f6c3a8', '1efa3501-4594-518d-a00d-0657c11deb7d', 'The shortest one', 'A', false, 0),
('29e2662c-151b-5066-a840-f9dd92d5699b', '1efa3501-4594-518d-a00d-0657c11deb7d', 'The longest one', 'B', false, 1),
('c3e9766b-c757-5d3b-8cf8-69941073f6bb', '1efa3501-4594-518d-a00d-0657c11deb7d', 'The one with the same length as the driver', 'C', true, 2),
('0f439dec-0a15-5d73-8c43-f13f7eaad560', '1efa3501-4594-518d-a00d-0657c11deb7d', 'The lightest one', 'D', false, 3),
('03e061da-cd85-589d-b4e3-03fe6ee40bca', 'd99bffe3-6bea-5252-a09f-187f159f0990', 'Marching in step could drive the bridge at its natural frequency and cause resonance', 'A', true, 0),
('df7f697d-9613-5a5a-9326-16f1f7f76cb8', 'd99bffe3-6bea-5252-a09f-187f159f0990', 'To reduce the weight on the bridge', 'B', false, 1),
