('14b1b00b-3c54-5fbb-b6f6-e0ebcdcf0dad', '7222acfc-b669-50dd-8f9f-e727ce29ebf3', 'It rises to a very large, sharp peak at the natural frequency', 'B', true, 1),
('a36850f5-dcc2-5358-a1c5-ead05cf980eb', '7222acfc-b669-50dd-8f9f-e727ce29ebf3', 'It falls to zero at the natural frequency', 'C', false, 2),
('82c11b65-40f2-5124-a5ef-558faf5a9149', '7222acfc-b669-50dd-8f9f-e727ce29ebf3', 'It rises steadily with frequency', 'D', false, 3),
('4c6c7894-f583-5adb-aae0-2ed7d463cab9', '2ef8914e-68fb-5f24-a0d5-709ef5cf06d6', 'Free oscillation', 'A', false, 0),
('37057c73-ec96-5b70-9e8c-16c6e531b632', '2ef8914e-68fb-5f24-a0d5-709ef5cf06d6', 'Damped free oscillation', 'B', false, 1),
('c5e61e2b-ed2b-5278-9cf2-f887d82c1d8d', '2ef8914e-68fb-5f24-a0d5-709ef5cf06d6', 'Forced oscillation', 'C', true, 2),
('56adaadf-36bb-5c07-9d6a-7e795a5c0a66', '2ef8914e-68fb-5f24-a0d5-709ef5cf06d6', 'Critical oscillation', 'D', false, 3),
('488a29f0-ebf6-5d10-bbce-2acaeb4144d5', '06647ffd-870b-5500-a65f-cf54a1aa390c', 'To avoid resonance, which would give dangerously large oscillations', 'A', true, 0),
('8244b842-372a-5330-b828-23b91649dd68', '06647ffd-870b-5500-a65f-cf54a1aa390c', 'To make the building lighter', 'B', false, 1),
('ac545dfd-31d3-585e-ab29-d853513a31d5', '06647ffd-870b-5500-a65f-cf54a1aa390c', 'To reduce damping', 'C', false, 2),
